// xlsx is one of the heaviest packages in this app (several hundred KB on
// its own) but only ever needed for the admin's Excel import/export — every
// parent or coach just logging in or paying fees was downloading it too,
// even though they'd never touch it. Loading it on demand, only the moment
// an import/export actually happens, keeps it out of everyone else's way.
let _xlsxModule = null;
async function loadXLSX() {
  if (!_xlsxModule) _xlsxModule = await import("xlsx");
  return _xlsxModule;
}

// jsQR and QRCode power the staff QR check-in/check-out flow — the code
// generation (an admin-only screen) and the scanner (only opened when
// someone taps "Scan to check in"), neither of which happens on a
// typical login. Bundling them in eagerly meant every parent and coach
// downloaded both libraries just to log in and never use them; loading
// them only when the check-in screen actually opens keeps that weight
// out of everyone else's way, the same reasoning as xlsx above.
let _jsQRModule = null;
async function loadJsQR() {
  if (!_jsQRModule) _jsQRModule = (await import("jsqr")).default;
  return _jsQRModule;
}
let _qrcodeModule = null;
async function loadQRCode() {
  if (!_qrcodeModule) _qrcodeModule = (await import("qrcode")).default;
  return _qrcodeModule;
}

// The single fixed code printed and hung at the pool entrance — every
// coach/staff member scans this SAME code with their own phone camera,
// from inside their own logged-in dashboard, to check themselves in or
// out. Change this if the poster is ever lost/copied and needs replacing.
const STAFF_CHECKIN_CODE = "BOOST-HUB-STAFF-CHECKIN";

/* ============================================================
   Standalone storage — replaces Claude's built-in artifact storage
   with a real Supabase table, so the app works as an independent
   site with no dependency on claude.ai. Every read/write in this
   file goes through window.storage.get/set/delete (the same shape
   Claude's storage used), so nothing else in the file needed to
   change — this shim is the only new piece.
   See README.md for the one-time Supabase table setup (SQL included).
   ============================================================ */
const supabase = createClient(
  import.meta.env.VITE_SUPABASE_URL,
  import.meta.env.VITE_SUPABASE_ANON_KEY
);

// Creates a brand-new Auth user (email + password) WITHOUT touching the
// current admin's own signed-in session — used when an admin sets up a
// colleague's email login from the dashboard. A normal supabase.auth.signUp()
// call on the shared client would sign the admin themselves out and switch
// to the new account instead, since a client only ever holds one session at
// a time. This uses a separate, throwaway client (same project, its own
// isolated session that's never persisted) purely to create the user, so
// the admin's own session is completely unaffected.
async function createAuthUserWithoutSession(email, password) {
  const tempClient = createClient(import.meta.env.VITE_SUPABASE_URL, import.meta.env.VITE_SUPABASE_ANON_KEY, {
    auth: { persistSession: false, autoRefreshToken: false },
  });
  const { data, error } = await tempClient.auth.signUp({ email, password });
  return { data, error };
}

/* ============================================================
   Multi-academy support — which academy is this visitor/admin on?
   Determined once, from the URL path (e.g. yoursite.com/boost-hub ->
   slug "boost-hub"), and cached on `window.__academy` for the whole
   session. Every read/write below is scoped to this academy's id —
   this is what keeps one academy's data from mixing with another's.
   ============================================================ */
window.__academy = null; // { id, slug, name, logoDataUri, instapayHandle, instapayPhone } once resolved

function academySlugFromPath() {
  const seg = window.location.pathname.split("/").filter(Boolean)[0];
  return seg || null;
}

function secondPathSegment() {
  const seg = window.location.pathname.split("/").filter(Boolean)[1];
  return seg || null;
}

