// True unless the super admin has explicitly switched this tab off for
// the current academy — an academy nobody's ever touched this setting
// for (disabledFeatures missing or empty) keeps every tab, same as
// before this feature existed.
function isTabEnabled(key) {
  return !(window.__academy?.disabledFeatures || []).includes(key);
}

async function resolveAcademy() {
  const slug = academySlugFromPath();
  // No slug in the URL — this is the plain link that was already shared
  // with everyone before multi-academy support existed. Keep it pointing
  // at the original academy so nothing breaks for people already using it.
  let result;
  try {
    if (slug) {
      result = await supabase
        .from("academies")
        .select("id, name, slug, logo_data_uri, instapay_handle, instapay_phone, hero_data_uri, subscription_paid_until, primary_color, contact_phone, whatsapp, facebook_url, instagram_url, disabled_features")
        .eq("slug", slug)
        .maybeSingle();
    } else {
      result = await supabase
        .from("academies")
        .select("id, name, slug, logo_data_uri, instapay_handle, instapay_phone, hero_data_uri, subscription_paid_until, primary_color, contact_phone, whatsapp, facebook_url, instagram_url, disabled_features")
        .eq("id", "354f7151-03f6-4511-b40a-19db46f28e29")
        .maybeSingle();
    }
  } catch (e) {
    window.__academyError = String(e?.message || e);
    return null;
  }
  const { data, error } = result;
  if (error) {
    window.__academyError = error.message || JSON.stringify(error);
    return null;
  }
  if (!data) {
    window.__academyError = `No academy row matched (slug="${slug || "none"}")`;
    return null;
  }
  window.__academy = {
    id: data.id,
    slug: data.slug,
    name: data.name,
    logoDataUri: data.logo_data_uri,
    instapayHandle: data.instapay_handle,
    instapayPhone: data.instapay_phone,
    // A null date means "no expiry set" (unrestricted) — matches the
    // database-side RLS check that actually enforces this on writes.
    subscriptionExpired: !!(data.subscription_paid_until && data.subscription_paid_until < todayISO()),
    subscriptionPaidUntil: data.subscription_paid_until || null,
    primaryColor: data.primary_color || "#0369a1",
    contactPhone: data.contact_phone || "",
    whatsapp: data.whatsapp || "",
    facebookUrl: data.facebook_url || "",
    instagramUrl: data.instagram_url || "",
    // A list of tab keys the super admin has switched off for this
    // academy specifically — empty by default, so an academy created
    // before this existed (or one nobody's ever touched this setting
    // for) keeps every tab it already had.
    disabledFeatures: Array.isArray(data.disabled_features) ? data.disabled_features : [],
  };
  CONFIG.primaryColor = window.__academy.primaryColor;
  // Every place in the app that reads CONFIG.academyName / logoDataUri /
  // instapayHandle / instapayPhone now shows THIS academy's own values —
  // falls back to the built-in defaults for anything the academy hasn't
  // set yet (e.g. no custom logo uploaded), rather than showing blank.
  if (data.name) CONFIG.academyName = data.name;
  if (data.logo_data_uri) CONFIG.logoDataUri = data.logo_data_uri;
  if (data.instapay_handle) CONFIG.instapayHandle = data.instapay_handle;
  if (data.instapay_phone) CONFIG.instapayPhone = data.instapay_phone;
  // Note: hero photos are NOT read from here anymore — the Settings tab's
  // homepage content (loaded separately, see loadHomepageContent) is the
  // one source of truth for those now, so there's no longer a legacy
  // value that could race with it and cause a visible flash on load.
  return window.__academy;
}

// Lets the academy's own admin (not just the super admin) update their
// name, logo, and Instapay details from their own dashboard — writes
// straight to this academy's row, and updates CONFIG + window.__academy
// immediately so the change shows everywhere without needing a refresh.
async function saveAcademySettings({ name, logoDataUri, instapayHandle, instapayPhone, primaryColor }) {
  if (!window.__academy) throw new Error("No academy selected");
  const { error } = await supabase
    .from("academies")
    .update({
      name,
      logo_data_uri: logoDataUri,
      instapay_handle: instapayHandle,
      instapay_phone: instapayPhone,
      ...(primaryColor ? { primary_color: primaryColor } : {}),
    })
    .eq("id", window.__academy.id);
  if (error) throw error;
  CONFIG.academyName = name;
  CONFIG.logoDataUri = logoDataUri;
  CONFIG.instapayHandle = instapayHandle;
  CONFIG.instapayPhone = instapayPhone;
  if (primaryColor) CONFIG.primaryColor = primaryColor;
  window.__academy = { ...window.__academy, name, logoDataUri, instapayHandle, instapayPhone, ...(primaryColor ? { primaryColor } : {}) };
}

/* ============================================================
   Real Supabase Auth for staff — this is the migration path off
   the old shared/plaintext-password logins. Every staff member
   keeps working through their existing username/password until
   they set up a real email login (self-serve, from the staff
   login screen); once they do, their "account" record (role,
   permissions — still the source of truth for those) is linked
   to their real Auth user via authUserId, and future logins go
   through supabase.auth instead of comparing a stored password.
   ============================================================ */

// Checks that a signed-in Supabase Auth user is actually linked to the
// academy this link belongs to (or is a super admin, who can access any
// academy). Shared by every real-auth login screen in the app (admin,
// staff, and the "already signed in" auto-check on mount).
async function verifyProfileForThisAcademy(userId) {
  const { data: profile, error: profileError } = await supabase
    .from("profiles")
    .select("academy_id, is_super_admin")
    .eq("id", userId)
    .maybeSingle();
  if (profileError || !profile) return false;
  if (!profile.is_super_admin && profile.academy_id !== window.__academy?.id) return false;
  return true;
}

// Runs once right after a staff member's first successful real-auth
// sign-in (whether that's moments after they just set up their email
// login, or a normal sign-in on a later day): makes sure they have a
// "profiles" row for this academy, and — if a matching legacy account
// username was supplied — links that account record to this real Auth
// user (authUserId) so future logins resolve their role/permissions
// through the real session instead of the old stored password. Safe to
// call every time; it's a no-op once both are already in place.
async function ensureStaffProfileAndLink(user, matchingAccountUsername) {
  let { data: profile } = await supabase
    .from("profiles")
    .select("academy_id, is_super_admin")
    .eq("id", user.id)
    .maybeSingle();
  if (!profile) {
    const { error } = await supabase
      .from("profiles")
      .insert({ id: user.id, academy_id: window.__academy.id, is_super_admin: false });
    if (error) throw error;
    profile = { academy_id: window.__academy.id, is_super_admin: false };
  }
  if (matchingAccountUsername) {
    const accounts = await loadCollection(STORE_KEYS.accounts);
    const idx = accounts.findIndex((a) => a.username.toLowerCase() === matchingAccountUsername.toLowerCase());
    if (idx !== -1 && accounts[idx].authUserId !== user.id) {
      const next = [...accounts];
      next[idx] = { ...next[idx], authUserId: user.id, email: user.email };
      await saveCollection(STORE_KEYS.accounts, next);
    }
  }
  return profile;
}

// After a real-auth staff sign-in, finds the matching staff account
// record (role, permissions, linked coach, restrictions) by authUserId —
// this is what lets the rest of the app keep working exactly as it does
// today (routing by account.role) once someone's on the new login.
async function findAccountByAuthUserId(userId) {
  const accounts = await loadCollection(STORE_KEYS.accounts);
  return accounts.find((a) => a.authUserId === userId) || null;
}

window.storage = {
  async get(key) {
    if (!window.__academy) return null;
    const { data, error } = await supabase
      .from("app_storage")
      .select("value")
      .eq("key", key)
      .eq("academy_id", window.__academy.id)
      .maybeSingle();
    if (error) throw error;
    return data ? { key, value: data.value } : null;
  },
  async set(key, value) {
    if (!window.__academy) throw new Error("No academy selected — check the link you're using");
    const { error } = await supabase
      .from("app_storage")
      .upsert({ key, value, academy_id: window.__academy.id, updated_at: new Date().toISOString() });
    if (error) throw error;
    return { key, value };
  },
  async delete(key) {
    if (!window.__academy) return null;
    const { error } = await supabase
      .from("app_storage")
      .delete()
      .eq("key", key)
      .eq("academy_id", window.__academy.id);
    if (error) return null;
    return { key, deleted: true };
  },
};

// Platform-level settings (subscription plan prices/discounts, the
// platform owner's own Instapay details, and the log of academies paying
// to renew) all live in the platform_settings table's single row — a
// separate table with no per-academy foreign key, since this data isn't
// scoped to any one academy the way app_storage rows are.
const DEFAULT_SUBSCRIPTION_PLANS = {
  monthly: { label: "Monthly", months: 1, price: 500, discount: 0 },
  semiannual: { label: "Every 6 months", months: 6, price: 2700, discount: 10 },
  annual: { label: "Yearly", months: 12, price: 5000, discount: 20 },
};

async function loadSubscriptionPlans() {
  try {
    const { data, error } = await supabase.from("platform_settings").select("subscription_plans").eq("id", true).maybeSingle();
    if (error || !data?.subscription_plans) return DEFAULT_SUBSCRIPTION_PLANS;
    const parsed = typeof data.subscription_plans === "string" ? JSON.parse(data.subscription_plans) : data.subscription_plans;
    return { ...DEFAULT_SUBSCRIPTION_PLANS, ...parsed };
  } catch {
    return DEFAULT_SUBSCRIPTION_PLANS;
  }
}

async function saveSubscriptionPlans(plans) {
  const { error } = await supabase.from("platform_settings").update({ subscription_plans: plans }).eq("id", true);
  if (error) throw error;
  return true;
}

// The platform owner's own Instapay details — where academies send their
// subscription payment to, as distinct from each academy's own Instapay
// (which is where THEIR swim parents pay THEM). Marked "temporary" in the
// UI since this is a manual review flow, not a real payment gateway yet.
async function loadPlatformInstapay() {
  try {
    const { data, error } = await supabase.from("platform_settings").select("instapay_handle, instapay_phone").eq("id", true).maybeSingle();
    if (error || !data) return { handle: "", phone: "" };
    return { handle: data.instapay_handle || "", phone: data.instapay_phone || "" };
  } catch {
    return { handle: "", phone: "" };
  }
}

async function savePlatformInstapay(info) {
  const { error } = await supabase.from("platform_settings").update({ instapay_handle: info.handle || null, instapay_phone: info.phone || null }).eq("id", true);
  if (error) throw error;
  return true;
}

