const CERT_TEMPLATE_KEY = "certificate-template";

async function loadCertTemplate() {
  const res = await window.storage.get(CERT_TEMPLATE_KEY);
  if (!res) return null;
  try {
    return JSON.parse(res.value);
  } catch {
    return null;
  }
}

async function saveCertTemplate(template) {
  return storageSet(CERT_TEMPLATE_KEY, JSON.stringify(template));
}

// Certificate look — a primary color and a font choice, both editable in
// Settings. The color can also be set to "auto", meaning: derive it from
// whatever the current logo actually looks like, so re-branding the logo
// automatically re-colors certificates too without a separate step.
const CERT_DESIGN_KEY = "certificate-design";
const CERT_FONTS = {
  serif: { label: "Classic Serif", body: "Georgia, 'Times New Roman', serif", ui: "-apple-system, Arial, sans-serif" },
  sans: { label: "Modern Sans", body: "-apple-system, 'Helvetica Neue', Arial, sans-serif", ui: "-apple-system, Arial, sans-serif" },
  elegant: { label: "Elegant", body: "'Playfair Display', Georgia, serif", ui: "-apple-system, Arial, sans-serif" },
};

async function loadCertDesign() {
  try {
    const res = await window.storage.get(CERT_DESIGN_KEY);
    if (!res) return { color: "auto", font: "serif" };
    const parsed = JSON.parse(res.value);
    return { color: parsed.color || "auto", font: parsed.font || "serif" };
  } catch {
    return { color: "auto", font: "serif" };
  }
}

async function saveCertDesign(design) {
  return storageSet(CERT_DESIGN_KEY, JSON.stringify(design));
}

// Samples the logo image on a canvas and returns its most common
// non-white, non-transparent color as a hex string — this is what "auto"
// mode uses, so the certificate always matches whatever logo is current
// without anyone needing to manually pick a matching color.
function extractDominantColor(dataUri) {
  return new Promise((resolve) => {
    const fallback = "#0b1e3a";
    if (!dataUri) return resolve(fallback);
    const img = new Image();
    img.onload = () => {
      try {
        const size = 40; // downsample for speed — color counting doesn't need full resolution
        const canvas = document.createElement("canvas");
        canvas.width = size;
        canvas.height = size;
        const ctx = canvas.getContext("2d");
        ctx.drawImage(img, 0, 0, size, size);
        const { data } = ctx.getImageData(0, 0, size, size);
        const counts = {};
        for (let i = 0; i < data.length; i += 4) {
          const [r, g, b, a] = [data[i], data[i + 1], data[i + 2], data[i + 3]];
          if (a < 200) continue; // skip transparent pixels
          const brightness = (r + g + b) / 3;
          if (brightness > 235) continue; // skip near-white background
          if (brightness < 20) continue; // skip near-black (often just text/outline)
          // Bucket similar colors together so near-identical shades count as one
          const key = `${Math.round(r / 16)},${Math.round(g / 16)},${Math.round(b / 16)}`;
          if (!counts[key]) counts[key] = { r: 0, g: 0, b: 0, n: 0 };
          counts[key].r += r;
          counts[key].g += g;
          counts[key].b += b;
          counts[key].n += 1;
        }
        const buckets = Object.values(counts).sort((a, b) => b.n - a.n);
        if (buckets.length === 0) return resolve(fallback);
        const top = buckets[0];
        const toHex = (v) => Math.round(v / top.n).toString(16).padStart(2, "0");
        resolve(`#${toHex(top.r)}${toHex(top.g)}${toHex(top.b)}`);
      } catch (e) {
        resolve(fallback); // e.g. a tainted canvas from a cross-origin image
      }
    };
    img.onerror = () => resolve(fallback);
    img.src = dataUri;
  });
}


/* Available start times per branch + day group. This starts out as the
   built-in default — the "Settings" tab in the admin dashboard lets the
   academy customize its own time slots, saved to storage and merged in
   on load, same pattern as LEVEL_SKILLS below. */
let TIME_SLOTS = {
  elalsson: {
    "sun-tue": ["3:30 PM", "4:30 PM", "5:30 PM", "6:30 PM", "7:30 PM", "8:30 PM", "9:30 PM"],
    "mon-wed": ["3:30 PM", "4:30 PM", "5:30 PM", "6:30 PM", "7:30 PM", "8:30 PM", "9:30 PM"],
    "fri-sat": ["8:30 AM", "10:00 AM", "10:30 AM", "11:00 AM", "11:30 AM", "12:00 PM", "12:30 PM", "1:00 PM", "1:30 PM", "2:00 PM", "2:30 PM", "3:00 PM", "3:30 PM", "4:00 PM", "5:00 PM", "6:00 PM"],
  },
};
const DEFAULT_TIME_SLOTS = JSON.parse(JSON.stringify(TIME_SLOTS));


/* ============================================================
   Helpers
   ============================================================ */

/* Baby classes run on their own fully independent time slots (see
   BABY_TIME_SLOTS above) — separate from and not derived from the
   regular hourly slots at all. */
function getTimeOptions(branch, day, level) {
  if (level === "Baby") return (BABY_TIME_SLOTS[branch] && BABY_TIME_SLOTS[branch][day]) || [];
  return (TIME_SLOTS[branch] && TIME_SLOTS[branch][day]) || [];
}

function compressImage(file, maxWidth = 900, quality = 0.72, preserveTransparency = false) {
  return new Promise((resolve, reject) => {
    // Reading via an object URL (a lightweight reference to the file) is
    // far more memory-friendly than base64-encoding the whole file first —
    // a full-size phone camera photo (often 8-12MB) could otherwise fail
    // to load at all on lower-memory devices before it ever reaches the
    // canvas below.
    const objectUrl = URL.createObjectURL(file);
    const img = new Image();
    img.onload = () => {
      try {
        const scale = Math.min(1, maxWidth / img.width);
        const canvas = document.createElement("canvas");
        canvas.width = Math.max(1, Math.round(img.width * scale));
        canvas.height = Math.max(1, Math.round(img.height * scale));
        const ctx = canvas.getContext("2d");
        ctx.drawImage(img, 0, 0, canvas.width, canvas.height);
        // JPEG has no transparency channel — any see-through area of the
        // original gets silently filled in as solid black on export.
        // Logos are usually exactly the case where that transparent
        // background is the whole point, so those are kept as PNG
        // instead; everything else (photos, payment screenshots) stays
        // JPEG, since PNG would make them noticeably larger for no
        // visible benefit.
        resolve(preserveTransparency ? canvas.toDataURL("image/png") : canvas.toDataURL("image/jpeg", quality));
      } catch (e) {
        reject(e);
      } finally {
        URL.revokeObjectURL(objectUrl);
      }
    };
    img.onerror = () => {
      URL.revokeObjectURL(objectUrl);
      reject(new Error("Could not load that image — try a different photo or a screenshot of it"));
    };
    img.src = objectUrl;
  });
}

function genId() {
  return Date.now().toString(36) + Math.random().toString(36).slice(2, 7);
}

function genParentPin() {
  return String(Math.floor(1000 + Math.random() * 9000));
}

function escapeHtml(str) {
  return String(str ?? "").replace(/[&<>"']/g, (c) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" }[c]));
}

/* Artifacts run inside a sandboxed preview frame, where window.print() is
   often blocked silently. Instead, build a standalone HTML file and
   download it — opening that file in a normal browser tab lets the person
   print it / "Save as PDF" with no sandbox restrictions. */
function downloadReportHTML(filename, bodyHtml) {
  const html = `<!DOCTYPE html><html><head><meta charset="utf-8"><title>${escapeHtml(filename)}</title>
<style>
  * { -webkit-print-color-adjust: exact !important; print-color-adjust: exact !important; color-adjust: exact !important; }
  body { font-family: -apple-system, Segoe UI, Roboto, Arial, sans-serif; color: #1e293b; padding: 32px; max-width: 800px; margin: 0 auto; }
  h1 { font-size: 18px; margin: 0 0 4px; }
  .sub { color: #64748b; font-size: 13px; margin-bottom: 24px; }
  .header { display: flex; align-items: center; gap: 12px; margin-bottom: 24px; }
  .header img { width: 40px; height: 40px; object-fit: contain; }
  .cards { display: grid; grid-template-columns: repeat(4, 1fr); gap: 10px; margin-bottom: 20px; }
  .card { border: 1px solid #e2e8f0; border-radius: 10px; padding: 10px; text-align: center; }
  .card .num { font-size: 20px; font-weight: 700; }
  .card .lbl { font-size: 11px; color: #94a3b8; }
  h3 { font-size: 14px; margin: 24px 0 8px; }
  table { width: 100%; border-collapse: collapse; font-size: 13px; margin-bottom: 16px; }
  th, td { text-align: left; padding: 6px 10px; border-bottom: 1px solid #f1f5f9; }
  th { color: #64748b; font-size: 11px; background: #f8fafc; }
  .green { color: #16a34a; font-weight: 600; }
  .red { color: #ef4444; font-weight: 600; }
  .notes-cell { min-width: 90px; }
  .plan-header { font-size: 12px; font-weight: 700; color: #0b1e3a; background: #eef2ff; padding: 5px 10px; margin-top: 10px; border: 1px solid #c7d2fe; border-bottom: none; }
  .plan-count { font-weight: 400; color: #64748b; }
  .roster-grid table { border: 1px solid #cbd5e1; }
  .roster-grid th, .roster-grid td { border: 1px solid #cbd5e1; padding: 5px 8px; text-align: inherit; }
  .roster-grid th { background: #f1f5f9; }
  .roster-grid tr:nth-child(even) td { background: #fafbfc; }
  .roster-grid .blank-row td { background: #ffffff; height: 22px; }
  .coach-block { page-break-inside: avoid; break-inside: avoid; }
  @media print { body { padding: 0; } }
</style></head><body>${bodyHtml}
<script>window.onload = () => setTimeout(() => window.print(), 300);</script>
</body></html>`;
  const blob = new Blob([html], { type: "text/html" });
  const url = URL.createObjectURL(blob);
  const a = document.createElement("a");
  a.href = url;
  a.download = filename.endsWith(".html") ? filename : `${filename}.html`;
  document.body.appendChild(a);
  a.click();
  document.body.removeChild(a);
  setTimeout(() => URL.revokeObjectURL(url), 2000);
}

