/* Staff account roles and what each one can do:
   - admin: everything (same as the old single admin password)
   - branch_manager: view-only — same screens as admin, no edit/create/delete
   - technical: search a swimmer by name and check them in IF they're
     already registered — can't create swimmers or see anything else */
const ROLES = [
  { id: "admin", label: "Admin (full access)" },
  { id: "branch_admin", label: "Branch admin manager (full access)" },
  { id: "branch_manager", label: "Branch manager (view only)" },
  { id: "technical_director", label: "Technical director (assigns coaches to swimmers)" },
  { id: "technical", label: "Technical (search & check-in only)" },
  { id: "coach", label: "Coach (own schedule & swimmers only)" },
];

// Granular permissions. Roles provide sensible defaults, while each account
// can override them individually. Program/level access is separate from
// the coach's own roster so a STAR lead can follow STAR swimmers coached by
// other staff without gaining administrative access.
const PERMISSION_DEFS = [
  ["viewSwimmers", "View swimmers"],
  ["manageSwimmers", "Add / edit swimmers"],
  ["manageSchedule", "Create / edit / cancel bookings"],
  ["manageWaitlist", "Manage waitlist"],
  ["manageSubstitute", "Assign substitute coach"],
  ["viewSwimmerAttendance", "View swimmer attendance"],
  ["takeSwimmerAttendance", "Take swimmer attendance"],
  ["editOldAttendance", "Edit old swimmer attendance"],
  ["viewPayments", "View payment status / amounts"],
  ["recordPayments", "Record payments"],
  ["manageDiscounts", "Apply discounts"],
  ["refundPayments", "Refund / void payments"],
  ["viewFinancialReports", "View financial reports"],
  ["managePlans", "Manage plans / prices"],
  ["manageCoaches", "Add / edit coaches"],
  ["assignCoaches", "Change main coach"],
  ["viewCoachReports", "View coach reports / KPI"],
  ["manageCurriculum", "Manage levels / curriculum"],
  ["manageTrainingPlans", "Manage team training plans"],
  ["viewAssessments", "View swimmer assessments"],
  ["editAssessments", "Edit swimmer assessments"],
  ["viewStaffAttendance", "View staff attendance / payroll"],
  ["editStaffAttendance", "Edit staff attendance / payroll"],
  ["manageExpenses", "Manage expenses"],
  ["viewReports", "View general reports"],
  ["manageAccounts", "Manage staff accounts / permissions"],
];

const ROLE_DEFAULT_PERMISSIONS = {
  admin: Object.fromEntries(PERMISSION_DEFS.map(([k]) => [k, true])),
  branch_admin: Object.fromEntries(PERMISSION_DEFS.map(([k]) => [k, true])),
  branch_manager: { viewSwimmers:true, viewSwimmerAttendance:true, viewPayments:true, viewFinancialReports:true, viewCoachReports:true, viewAssessments:true, viewStaffAttendance:true, viewReports:true },
  technical_director: { viewSwimmers:true, manageSchedule:true, manageWaitlist:true, manageSubstitute:true, viewSwimmerAttendance:true, takeSwimmerAttendance:true, editOldAttendance:true, viewPayments:true, manageCoaches:true, assignCoaches:true, viewCoachReports:true, viewAssessments:true, editAssessments:true, viewReports:true },
  technical: { viewSwimmers:true, viewSwimmerAttendance:true, takeSwimmerAttendance:true, viewAssessments:true },
  coach: { viewSwimmers:true, viewSwimmerAttendance:true, takeSwimmerAttendance:true, viewAssessments:true, editAssessments:true },
};

const PROGRAM_LEVEL_SCOPE = {
  "Baby Swim Program": ["Baby"],
  "Learn to Swim": ["Level 1","Level 2","Level 3","Level 4","Level 5","Level 6","Level 7","Level 8"],
  "STAR": ["Star 1","Star 2","Star 3","Star 4"],
  "Development Swim": ["Star 1","Star 2","Star 3","Star 4","Team"],
  "Exp": ["Exp","Exp 2","Exp 3"],
};

function getAccountPermissions(account, role) {
  if (role === "admin") return Object.fromEntries(PERMISSION_DEFS.map(([k]) => [k, true]));
  const base = { ...(ROLE_DEFAULT_PERMISSIONS[role] || {}) };
  const overrides = account?.permissions || {};
  for (const [key] of PERMISSION_DEFS) {
    if (typeof overrides[key] === "boolean") base[key] = overrides[key];
  }
  return base;
}

// Builds a readable summary of what actually changed on a staff account —
// role and/or individual permissions — so the Activity Log shows exactly
// what was granted or revoked, not just "Edited account".
function describeAccountChange(oldAccount, newAccount) {
  if (!oldAccount) {
    const role = newAccount.role || "—";
    const perms = getAccountPermissions(newAccount, newAccount.role);
    const granted = PERMISSION_DEFS.filter(([k]) => perms[k]).map(([, label]) => label);
    return `role: ${role}${granted.length ? ` (${granted.join(", ")})` : ""}`;
  }
  const parts = [];
  if (oldAccount.role !== newAccount.role) {
    parts.push(`role: ${oldAccount.role || "—"} → ${newAccount.role || "—"}`);
  }
  if (oldAccount.name !== newAccount.name) {
    parts.push(`name: ${oldAccount.name || "—"} → ${newAccount.name || "—"}`);
  }
  const oldPerms = getAccountPermissions(oldAccount, oldAccount.role);
  const newPerms = getAccountPermissions(newAccount, newAccount.role);
  const added = PERMISSION_DEFS.filter(([k]) => newPerms[k] && !oldPerms[k]).map(([, label]) => label);
  const removed = PERMISSION_DEFS.filter(([k]) => !newPerms[k] && oldPerms[k]).map(([, label]) => label);
  if (added.length) parts.push(`+${added.join(", +")}`);
  if (removed.length) parts.push(`-${removed.join(", -")}`);
  return parts.length ? parts.join("; ") : "no changes";
}

function levelBelongsToProgram(level, program) {
  if (!program) return true;
  const levels = PROGRAM_LEVEL_SCOPE[program] || [];
  return levels.includes(level);
}


async function loadCollection(storeKey) {
  try {
    const res = await window.storage.get(storeKey, true);
    return res && res.value ? JSON.parse(res.value) : [];
  } catch {
    return [];
  }
}

async function saveCollection(storeKey, list) {
  const res = await storageSet(storeKey, JSON.stringify(list), true);
  // The "swimmers" table is a SEPARATE, denormalized copy of this same
  // data — kept only so search/pagination/session-roster queries can hit
  // Supabase directly instead of pulling the whole roster into memory.
  // Nothing else writes to it, so every save through here has to mirror
  // into it too, or that table just silently goes stale and every read
  // that depends on it (search, coach/staff rosters, capacity checks)
  // starts returning nothing.
  if (storeKey === STORE_KEYS.swimmers) {
    syncSwimmersTable(list).catch((e) => console.warn("swimmers table sync failed", e));
  }
  return res;
}

// Mirrors the full swimmers array into the dedicated "swimmers" table:
// upserts every current swimmer, then deletes any row for this academy
// that's no longer in the array (covers deletes and the "reset all").
// Fire-and-forget from saveCollection's point of view — a sync failure
// here shouldn't block the actual save the user was waiting on, but it
// does mean search/rosters can lag behind until the next successful save.
async function syncSwimmersTable(list) {
  if (!window.__academy) return;
  const academyId = window.__academy.id;
  const rows = list.map((s) => ({
    id: s.id,
    academy_id: academyId,
    name: s.name || "",
    branch: s.branch || null,
    level: s.level || null,
    data: s,
  }));
  if (rows.length > 0) {
    const { error } = await supabase.from("swimmers").upsert(rows, { onConflict: "id" });
    if (error) throw error;
  }
  const currentIds = list.map((s) => s.id);
  let delQuery = supabase.from("swimmers").delete().eq("academy_id", academyId);
  delQuery = currentIds.length > 0
    ? delQuery.not("id", "in", `(${currentIds.map((id) => `"${id}"`).join(",")})`)
    : delQuery; // empty list (e.g. "reset all") — delete every row for this academy
  const { error: delError } = await delQuery;
  if (delError) throw delError;
}

/* Payment screenshots are the one thing here that's genuinely heavy (each is
   a compressed JPEG data URI). Storage caps any single key's value at 5MB —
   if screenshots were merged into the subs-all array, that array would keep
   growing every time someone subscribes (nothing ever deletes old requests)
   and eventually blow past the cap, making every save fail permanently.
   So each screenshot lives under its own small key, separate from the
   lightweight request metadata in subs-all. */
function photoKeyFor(id) {
  return `shot:${id}`;
}

async function notifyTelegram(record) {
  // Sends via a server-side endpoint (/api/send-telegram-notification)
  // that holds the bot token itself, read from an environment variable —
  // the browser never sees it. Each academy has its own bot token/chat ID,
  // set up from Settings → "Telegram alerts"; academies that haven't
  // configured one just get a quiet no-op here (the endpoint checks and
  // skips sending, same as the old CONFIG check used to).
  try {
    await fetch("/api/send-telegram-notification", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({
        academyId: window.__academy?.id,
        text:
          `New subscription request\n` +
          `Name: ${record.name}\n` +
          `Phone: ${record.phone}\n` +
          `Plan: ${record.planName} (${record.price} EGP)\n` +
          `Code: ${record.id}`,
      }),
    });
  } catch (e) {
    console.warn("Telegram notify failed", e);
  }
}

/* Add minutes to a "H:MM AM/PM" string and return the same format */
function addMinutesToTime(timeStr, mins) {
  const [time, period] = timeStr.split(" ");
  let [h, m] = time.split(":").map(Number);
  if (period === "PM" && h !== 12) h += 12;
  if (period === "AM" && h === 12) h = 0;
  const base = new Date(2000, 0, 1, h, m);
  const end = new Date(base.getTime() + mins * 60000);
  let hh = end.getHours();
  const mm = end.getMinutes();
  const ampm = hh >= 12 ? "PM" : "AM";
  hh = hh % 12;
  if (hh === 0) hh = 12;
  return `${hh}:${mm.toString().padStart(2, "0")} ${ampm}`;
}

/* Minutes since midnight for a "H:MM AM/PM" string — for chronological sorting */
function timeToMinutes(timeStr) {
  if (!timeStr) return 0;
  const [time, period] = timeStr.split(" ");
  let [h, m] = time.split(":").map(Number);
  if (period === "PM" && h !== 12) h += 12;
  if (period === "AM" && h === 12) h = 0;
  return h * 60 + (m || 0);
}

function scheduleLabel(swimmer) {
  if (!swimmer.day || !swimmer.time) return "—";
  const duration = swimmer.level === "Baby" ? 30 : 60;
  const dayLabel = DAY_GROUPS.find((d) => d.id === swimmer.day)?.label || swimmer.day;
  const end = addMinutesToTime(swimmer.time, duration);
  return `${dayLabel} · ${swimmer.time} - ${end}`;
}

/* Month tracking for renewals — "2026-08" style keys */
function monthKey(date = new Date()) {
  return `${date.getFullYear()}-${String(date.getMonth() + 1).padStart(2, "0")}`;
}

function nextMonthKey(date = new Date()) {
  return monthKey(new Date(date.getFullYear(), date.getMonth() + 1, 1));
}

function monthLabel(key) {
  const [y, m] = key.split("-").map(Number);
  return new Date(y, m - 1, 1).toLocaleDateString("en-GB", { month: "long", year: "numeric" });
}

/* Which month a NEW payment coming in right now should count for. Once
   the admin's "next month opens on" date has arrived, everyone paying is
   pre-paying for NEXT month (this month is basically over) — so default
   to that instead of always assuming "this month", which was silently
   marking advance payments against the wrong month. Still just a
   default: wherever this is used, the admin can override it. */
function defaultPaymentMonth(bookingOpenDate) {
  if (bookingOpenDate && todayISO() >= bookingOpenDate) return nextMonthKey();
  return monthKey();
}

function isPaidThisMonth(swimmer) {
  return (swimmer.paidMonths || []).includes(monthKey());
}

/* ---------- Freeze (pause subscription) ----------
   A swimmer can be frozen for N days: we store the date the freeze ends
   (frozenUntil, an ISO date string) plus a small log for the admin's
   reference. While today <= frozenUntil, the swimmer is treated as "on
   hold" — not nagged for payment and not auto-unscheduled — even if this
   month isn't marked paid. Once frozenUntil passes, everything goes back
   to normal automatically (no cleanup job needed). */
function isFrozen(swimmer) {
  return !!swimmer.frozenUntil && swimmer.frozenUntil >= todayISO();
}

function addDaysISO(iso, days) {
  const d = new Date(iso + "T00:00:00");
  d.setDate(d.getDate() + Number(days || 0));
  return toISODate(d);
}

/* Freezing pushes the due date back by the given number of days, starting
   from whichever is later — today, or the swimmer's current freeze end
   (so stacking a second freeze on top of an active one extends it,
   instead of overwriting it with a shorter one). */
function freezeSwimmer(swimmer, days, note) {
  const base = isFrozen(swimmer) ? swimmer.frozenUntil : todayISO();
  const frozenUntil = addDaysISO(base, days);
  const entry = { id: genId(), days: Number(days), note: note || "", date: new Date().toISOString() };
  return {
    ...swimmer,
    frozenUntil,
    freezeLog: [...(swimmer.freezeLog || []), entry],
  };
}

function unfreezeSwimmer(swimmer) {
  return { ...swimmer, frozenUntil: null };
}

/* Once a swimmer's subscription month rolls over without being renewed,
   their day/time slot is released (so it doesn't sit blocked forever) —
   name, phone and level are kept, only the schedule is cleared.
   A frozen swimmer is exempt — their spot stays reserved while frozen. */
// Once the real calendar reaches whatever month a swimmer's nextSchedule
// was pre-booked for, that becomes their live schedule — this runs
// alongside clearedIfUnpaid, once per calendar month, so an advance
// booking made while last month was still running switches over
// automatically without anyone having to remember to do it by hand.
function promotedIfDue(swimmer, currentMonthKey) {
  const monthly = swimmer.monthlySchedules?.[currentMonthKey];
  const source = monthly || (swimmer.nextSchedule?.scheduleMonth === currentMonthKey ? swimmer.nextSchedule : null);
  if (!source) return swimmer;
  const { day, time, sessionType, coachId, day2, time2, sessionType2, coachId2, classId, substituteCoachId, substituteDate } = source;
  return {
    ...swimmer,
    day: day || "", time: time || "", sessionType: sessionType || "group", coachId: coachId || null,
    day2: day2 || "", time2: time2 || "", sessionType2: sessionType2 || "", coachId2: coachId2 || null,
    classId: classId || classIdForSchedule({ branch: swimmer.branch, level: swimmer.level, day, time, sessionType, month: currentMonthKey }),
    substituteCoachId: substituteCoachId || null, substituteDate: substituteDate || "",
    scheduleMonth: currentMonthKey,
    nextSchedule: null,
  };
}

function clearedIfUnpaid(swimmer) {
  if (isPaidThisMonth(swimmer)) return swimmer;
  if (isFrozen(swimmer)) return swimmer;
  if (!swimmer.day && !swimmer.time) return swimmer;
  return { ...swimmer, day: "", time: "", coachId: null, scheduleMonth: "" };
}

/* ---------- WhatsApp click-to-chat ----------
   Builds a wa.me link for a stored phone number. Handles the common
   Egyptian local format (0XXXXXXXXXX) by swapping the leading 0 for the
   country code 20; leaves anything already in international form alone. */
function waPhoneDigits(phone) {
  const digits = String(phone || "").replace(/\D/g, "");
  if (!digits) return "";
  if (digits.startsWith("0") && digits.length === 11) return "20" + digits.slice(1);
  if (digits.startsWith("20")) return digits;
  return digits;
}

function waLink(phone, message = "") {
  const p = waPhoneDigits(phone);
  if (!p) return null;
  return `https://wa.me/${p}${message ? `?text=${encodeURIComponent(message)}` : ""}`;
}

function renewalWaMessage(swimmer) {
  return `مرحباً، معاك ${CONFIG.academyName}.\nتذكير بسيط إن اشتراك "${swimmer.name}" في السباحة محتاج تجديد. تقدر تدفع كاش أو عن طريق إنستاباي (${CONFIG.instapayHandle}) وتبعتلنا تأكيد الدفع.\nشكراً ليك!`;
}

/* A scheduled, non-frozen swimmer who hasn't paid this month yet — i.e.
   someone the admin should be nudging about renewal right now. */
function isDueForRenewal(swimmer) {
  return !!(swimmer.day && swimmer.time) && !isPaidThisMonth(swimmer) && !isFrozen(swimmer);
}

/* ---------- Roster-scale helpers ----------
   With a large roster (1000+ swimmers), holding everyone in React state
   just to render a page of 10-40 and search/filter client-side is what was
   making the Swimmers tab crash on phones. The swimmers table (see
   README) is the fast, searchable/paginated source for what gets
   DISPLAYED; these two helpers are for the few actions (payments,
   freezing, editing, importing...) that still need to safely read/update
   one swimmer within the FULL roster stored in Supabase — they fetch it
   fresh each time rather than keeping it sitting in memory. */
async function fetchAllSwimmers() {
  return await loadCollection(STORE_KEYS.swimmers);
}

// Edits queue up and run one at a time, in the order they were made —
// each waits for the previous save to actually finish before starting
// its own fetch, so two swimmer edits made close together (assigning a
// coach to one, then another, in quick succession) can never race and
// silently overwrite each other. Without this, the second save's
// "fetch everyone, change one, save everyone" cycle could read the list
// BEFORE the first save had finished writing, then write that stale copy
// back over it — quietly erasing whichever edit lost the race.
let swimmerUpdateQueue = Promise.resolve();

// Same protection, for the coach list — a coach save/delete fetches the
// list fresh (never the local React state, which could be stale if
// another edit landed since it was last loaded) and queues behind
// whichever coach edit is already in flight.
let coachUpdateQueue = Promise.resolve();

async function updateSwimmerById(id, updateFn) {
  const run = async () => {
    const all = await fetchAllSwimmers();
    const idx = all.findIndex((s) => s.id === id);
    if (idx === -1) throw new Error("Swimmer not found — try refreshing the list");
    const updated = updateFn(all[idx]);
    const next = [...all];
    next[idx] = updated;
    const res = await saveCollection(STORE_KEYS.swimmers, next);
    if (!res) throw new Error("Could not save, please try again");
    return updated;
  };
  // Chain onto the queue regardless of whether the previous entry
  // succeeded or failed, so one failed save never permanently blocks
  // every edit after it — but still WAIT for our own turn before running.
  const result = swimmerUpdateQueue.catch(() => {}).then(run);
  swimmerUpdateQueue = result.catch(() => {});
  return result;
}

const HISTORY_CLEANUP_KEY = "history-cleanup-settings";

async function loadHistoryCleanupSettings() {
  const res = await window.storage.get(HISTORY_CLEANUP_KEY);
  if (!res) return { enabled: false, lastRunMonth: null };
  try {
    return JSON.parse(res.value);
  } catch {
    return { enabled: false, lastRunMonth: null };
  }
}

async function saveHistoryCleanupSettings(settings) {
  return storageSet(HISTORY_CLEANUP_KEY, JSON.stringify(settings));
}

function monthsBetween(aKey, bKey) {
  const [ay, am] = aKey.split("-").map(Number);
  const [by, bm] = bKey.split("-").map(Number);
  return (by - ay) * 12 + (bm - am);
}

// Trims the detailed month-by-month level/schedule history down to the
// most recent months only — removes the 3 OLDEST calendar months found
// across every swimmer's levelHistory/scheduleHistory. Never touches
// names, phones, notes, or paidMonths (payment record stays complete).
async function runHistoryCleanup() {
  const all = await fetchAllSwimmers();
  const allMonthKeys = new Set();
  all.forEach((s) => {
    [...(s.levelHistory || []), ...(s.scheduleHistory || [])].forEach((h) => {
      if (h.date) allMonthKeys.add(h.date.slice(0, 7));
    });
  });
  const sortedMonths = [...allMonthKeys].sort();
  const monthsToRemove = new Set(sortedMonths.slice(0, 3));
  if (monthsToRemove.size === 0) return { removedMonths: [], swimmersTouched: 0 };

  let swimmersTouched = 0;
  const next = all.map((s) => {
    const newLevelHistory = (s.levelHistory || []).filter((h) => !monthsToRemove.has((h.date || "").slice(0, 7)));
    const newScheduleHistory = (s.scheduleHistory || []).filter((h) => !monthsToRemove.has((h.date || "").slice(0, 7)));
    if (newLevelHistory.length !== (s.levelHistory || []).length || newScheduleHistory.length !== (s.scheduleHistory || []).length) {
      swimmersTouched++;
      return { ...s, levelHistory: newLevelHistory, scheduleHistory: newScheduleHistory };
    }
    return s;
  });
  await saveCollection(STORE_KEYS.swimmers, next);
  return { removedMonths: [...monthsToRemove], swimmersTouched };
}

// Called once when the admin dashboard loads — checks whether it's been
// 6+ months since the last cleanup (or it's never run), and if so and
// it's turned on, runs it automatically without needing anyone to
// remember to do it by hand.
async function runHistoryCleanupIfDue() {
  const settings = await loadHistoryCleanupSettings();
  if (!settings.enabled) return null;
  const currentMonth = monthKey();
  if (settings.lastRunMonth && monthsBetween(settings.lastRunMonth, currentMonth) < 6) return null;
  const result = await runHistoryCleanup();
  await saveHistoryCleanupSettings({ ...settings, lastRunMonth: currentMonth });
  return result;
}

// Distance between two lat/lng points in meters (haversine formula) — used
// to check a GPS check-in actually happened near the pool, not the
// straight-line "as the crow flies" distance being an approximation
// people can fully trust down to the meter, but close enough to catch
// someone checking in from home.
function distanceMeters(lat1, lng1, lat2, lng2) {
  const R = 6371000;
  const toRad = (d) => (d * Math.PI) / 180;
  const dLat = toRad(lat2 - lat1);
  const dLng = toRad(lng2 - lng1);
  const a =
    Math.sin(dLat / 2) ** 2 +
    Math.cos(toRad(lat1)) * Math.cos(toRad(lat2)) * Math.sin(dLng / 2) ** 2;
  return R * 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1 - a));
}

// Reads the browser's current GPS position as a plain {lat, lng} object,
// or null if location isn't available/permitted — check-in still proceeds
// without it (see checkInStaff), it just won't be GPS-verified.
function getCurrentPositionSafe() {
  return new Promise((resolve) => {
    if (!navigator.geolocation) return resolve(null);
    navigator.geolocation.getCurrentPosition(
      (pos) => resolve({ lat: pos.coords.latitude, lng: pos.coords.longitude }),
      () => resolve(null),
      { enableHighAccuracy: true, timeout: 8000 }
    );
  });
}

// Compares a captured position against a branch's saved pool location —
// returns null when the branch has no location configured yet (nothing to
// check against, so GPS is simply not enforced), otherwise how far away
// they were and whether that's within the allowed radius.
function checkWithinBranchRadius(position, branch) {
  if (!branch?.lat || !branch?.lng) return null;
  if (!position) return { withinRadius: false, distance: null, noGps: true };
  const distance = Math.round(distanceMeters(position.lat, position.lng, branch.lat, branch.lng));
  const radius = Number(branch.radiusMeters) || 150;
  return { withinRadius: distance <= radius, distance, radius, noGps: false };
}

// Staff check-in/check-out — one record per person per day. Uses the
// account's own name (whoever's logged in) plus today's date as the key,
// so checking in twice the same day just updates the same record.
async function checkInStaff(accountName, role, position = null) {
  const all = await loadCollection(STORE_KEYS.staffAttendance);
  const today = todayISO();
  const idx = all.findIndex((r) => r.accountName === accountName && r.date === today);
  const now = new Date().toISOString();
  const gpsFields = position ? { checkInLat: position.lat, checkInLng: position.lng } : {};
  if (idx === -1) {
    all.push({ id: genId(), accountName, role, date: today, checkIn: now, checkOut: null, ...gpsFields });
  } else {
    all[idx] = { ...all[idx], checkIn: now, ...gpsFields };
  }
  await saveCollection(STORE_KEYS.staffAttendance, all);
  return all;
}

async function checkOutStaff(accountName, position = null) {
  const all = await loadCollection(STORE_KEYS.staffAttendance);
  const today = todayISO();
  const idx = all.findIndex((r) => r.accountName === accountName && r.date === today);
  if (idx !== -1) {
    const gpsFields = position ? { checkOutLat: position.lat, checkOutLng: position.lng } : {};
    all[idx] = { ...all[idx], checkOut: new Date().toISOString(), ...gpsFields };
    await saveCollection(STORE_KEYS.staffAttendance, all);
  }
  return all;
}

// The academy's shared payroll calendar — one weekly day off (e.g.
// Friday, for everyone), plus specific extra holiday dates added by
// hand each month (a multi-day break, a public holiday, whatever it is
// that month — no fixed count assumed). Stored once, academy-wide.
const PAYROLL_SETTINGS_KEY = "payroll-settings";
const WEEKDAY_NAMES = ["Sunday", "Monday", "Tuesday", "Wednesday", "Thursday", "Friday", "Saturday"];

async function loadPayrollSettings() {
  const res = await window.storage.get(PAYROLL_SETTINGS_KEY);
  if (!res) return { weeklyDayOff: null, extraHolidays: [] };
  try {
    const parsed = JSON.parse(res.value);
    return { weeklyDayOff: parsed.weeklyDayOff ?? null, extraHolidays: parsed.extraHolidays || [] };
  } catch {
    return { weeklyDayOff: null, extraHolidays: [] };
  }
}

// The academy's monthly training window — the admin sets exactly which
// dates this month's sessions actually run between (skipping vacation
// weeks), and how many sessions count as "this month's plan" (8 by
// default). Only affects the attendance columns shown on the session
// roster/report — not what staff can actually mark; they can still mark
// attendance any real day, this just decides what shows on the report.
const TRAINING_WINDOW_KEY = "training-window-settings";

async function loadTrainingWindowSettings() {
  const res = await window.storage.get(TRAINING_WINDOW_KEY);
  if (!res) return { startDate: "", endDate: "", cap: 8 };
  try {
    const parsed = JSON.parse(res.value);
    return { startDate: parsed.startDate || "", endDate: parsed.endDate || "", cap: parsed.cap || 8 };
  } catch {
    return { startDate: "", endDate: "", cap: 8 };
  }
}

async function saveTrainingWindowSettings(settings) {
  return storageSet(TRAINING_WINDOW_KEY, JSON.stringify(settings));
}

async function savePayrollSettings(settings) {
  return storageSet(PAYROLL_SETTINGS_KEY, JSON.stringify(settings));
}

// How many actual working days are in this month, given the weekly day
// off and any extra holiday dates that fall inside it.
function workingDaysInMonth(monthKeyStr, payrollSettings) {
  const [y, m] = monthKeyStr.split("-").map(Number);
  const daysInMonth = new Date(y, m, 0).getDate();
  const weeklyOffIndex = payrollSettings.weeklyDayOff ? WEEKDAY_NAMES.indexOf(payrollSettings.weeklyDayOff) : -1;
  let working = 0;
  for (let d = 1; d <= daysInMonth; d++) {
    const dateStr = `${monthKeyStr}-${String(d).padStart(2, "0")}`;
    const weekday = new Date(y, m - 1, d).getDay();
    if (weekday === weeklyOffIndex) continue;
    if ((payrollSettings.extraHolidays || []).includes(dateStr)) continue;
    working++;
  }
  return Math.max(working, 1); // never divide by zero
}

// Lateness deduction — 10 minute grace period after the account's
// expected start time, then 1-10 minutes late costs half an hour, and
// more than 10 minutes late costs half a day. Returns null if there's
// no expected time set, no check-in yet, or the record was manually
// marked excused (excused attendance never gets a deduction).
function computeLateDeduction(record, expectedStartTime) {
  if (!record?.checkIn || !expectedStartTime || record.excused) return null;
  const checkInDate = new Date(record.checkIn);
  const [eh, em] = expectedStartTime.split(":").map(Number);
  const expected = new Date(checkInDate);
  expected.setHours(eh, em, 0, 0);
  const lateMinutes = Math.round((checkInDate - expected) / 60000);
  if (lateMinutes <= 10) return null; // on time, or within the grace period
  if (lateMinutes <= 20) return { label: "−½ hour", minutesLate: lateMinutes, amountFraction: 1 / 16 };
  return { label: "−½ day", minutesLate: lateMinutes, amountFraction: 1 / 2 };
}

// Net pay for one person for one month — monthly salary minus whatever
// their late-checkin deductions add up to that month, plus any logged
// overtime at this person's own overtime rate. The daily rate is the
// salary divided by however many actual working days are in that month
// (not a flat 30) — set once for the whole academy in the Attendance
// tab (weekly day off + any extra holiday dates).
function computePayroll(account, records, monthKeyStr, payrollSettings, adjustments = []) {
  if (!account?.monthlySalary) return null;
  const workingDays = workingDaysInMonth(monthKeyStr, payrollSettings);
  const dailyRate = account.monthlySalary / workingDays;
  let totalDeduction = 0;
  const deductionEvents = [];
  let totalOvertimeHours = 0;
  records.forEach((r) => {
    const d = computeLateDeduction(r, account.expectedStartTime);
    if (d) {
      const amount = d.amountFraction === 1 / 2 ? dailyRate / 2 : dailyRate / 16;
      totalDeduction += amount;
      deductionEvents.push({ date: r.date, label: d.label, amount });
    }
    if (r.overtimeHours) totalOvertimeHours += Number(r.overtimeHours);
  });
  const overtimePay = totalOvertimeHours * (account.overtimeHourlyRate || 0);

  // Bonuses/manual deductions/advances the admin added by hand for this
  // person this month — on top of what's computed from attendance above.
  const mine = adjustments.filter((a) => a.accountName === account.name && a.month === monthKeyStr);
  const bonuses = mine.filter((a) => a.type === "bonus");
  const manualDeductions = mine.filter((a) => a.type === "deduction");
  const advances = mine.filter((a) => a.type === "advance");
  const totalBonuses = bonuses.reduce((s, a) => s + Number(a.amount || 0), 0);
  const totalManualDeductions = manualDeductions.reduce((s, a) => s + Number(a.amount || 0), 0);
  const totalAdvances = advances.reduce((s, a) => s + Number(a.amount || 0), 0);

  const approved = adjustments.some((a) => a.type === "approval" && a.accountName === account.name && a.month === monthKeyStr);

  return {
    base: account.monthlySalary,
    workingDays,
    totalDeduction,
    totalOvertimeHours,
    overtimePay,
    bonuses,
    manualDeductions,
    advances,
    totalBonuses,
    totalManualDeductions,
    totalAdvances,
    approved,
    net: account.monthlySalary - totalDeduction + overtimePay + totalBonuses - totalManualDeductions - totalAdvances,
    deductionEvents,
  };
}


function nextLevelOf(level) {
  const i = LEVELS.indexOf(level);
  if (i === -1 || i === LEVELS.length - 1) return null; // unknown level, or already at the top
  return LEVELS[i + 1];
}

function levelUpSwimmer(swimmer) {
  const to = nextLevelOf(swimmer.level);
  if (!to) return swimmer; // already at the highest level
  const completedLevel = swimmer.level; // the level they just finished
  return {
    ...swimmer,
    level: to,
    levelHistory: [...(swimmer.levelHistory || []), { level: to, date: new Date().toISOString() }],
    // Kept so the parent portal (and anyone else) can look back at and
    // re-print any certificate earned, not just the one just generated.
    certificates: [...(swimmer.certificates || []), { level: completedLevel, date: todayISO() }],
  };
}

/* The schedule-release above must run exactly once per calendar month —
   NOT on every load/poll — otherwise a schedule an admin just set (for a
   swimmer who isn't marked paid yet) would get wiped out again within
   seconds by the next 15s refresh. We remember the last month we already
   processed in shared storage, and only re-run the release when the
   current month is different from that. */
const SCHEDULE_RESET_KEY = "schedule-reset-month";

async function getLastScheduleResetMonth() {
  try {
    const res = await window.storage.get(SCHEDULE_RESET_KEY, true);
    return res?.value || null;
  } catch {
    return null;
  }
}

async function setLastScheduleResetMonth(key) {
  try {
    await storageSet(SCHEDULE_RESET_KEY, key, true);
  } catch {
    // non-fatal — worst case we re-check next load
  }
}

/* ---------- Next month's booking-open date ----------
   The admin sets one date (e.g. "the 24th") from the dashboard each month.
   Before that date, parents can still fill in the subscribe form, but
   can't actually send it — this is a single shared setting, not tied to
   a specific swimmer, so it's stored the same simple way as the schedule
   reset flag above. An empty/missing value means "no restriction". */
const BOOKING_OPEN_DATE_KEY = "booking-open-date";

async function getBookingOpenDate() {
  try {
    const res = await window.storage.get(BOOKING_OPEN_DATE_KEY, true);
    return res?.value || "";
  } catch {
    return "";
  }
}

async function setBookingOpenDate(dateStr) {
  await storageSet(BOOKING_OPEN_DATE_KEY, dateStr || "", true);
}

/* Swimmers a given coach already has booked in the same day+time slot
   (excludeId lets us ignore the swimmer currently being edited) */
function coachSlotUsage(swimmers, coachId, day, time, excludeId) {
  if (!coachId) return [];
  return swimmers.filter(
    (s) => s.coachId === coachId && s.day === day && s.time === time && s.id !== excludeId
  );
}

/* ============================================================
   Full-history import — for a sheet laid out with one 4-column block
   per month (payment / level / day / time), like an academy's
   month-by-month tracking sheet built up over a long time. Detected
   automatically: if the sheet doesn't look like this, the normal
   single-row importer below handles it instead.

   This rebuilds each swimmer's whole levelHistory + scheduleHistory
   from every month block that has real data (not just their current
   state) — same logic proven out for the offline edition's migration,
   ported here so it runs directly from the Import Excel button.
   ============================================================ */
const ARABIC_MONTH_NAMES = {
  "يناير": 1, "فبراير": 2, "مارس": 3, "أبريل": 4, "ابريل": 4, "مايو": 5, "يونيو": 6,
  "يوليو": 7, "أغسطس": 8, "اغسطس": 8, "سبتمبر": 9, "أكتوبر": 10, "اكتوبر": 10,
  "نوفمبر": 11, "ديسمبر": 12,
};

function parseMonthBlockLabel(label, prevYear, prevMonth) {
  const text = String(label || "").trim();
  let year = null;
  const yearMatch = text.match(/20\d{2}/);
  if (yearMatch) year = Number(yearMatch[0]);
  let month = null;
  for (const name of Object.keys(ARABIC_MONTH_NAMES)) {
    if (text.includes(name)) {
      month = ARABIC_MONTH_NAMES[name];
      break;
    }
  }
  if (month && !year) {
    // "شهر مارس" style, no year written — continue on from the previous
    // block's month/year in sequence (this month comes right after it).
    if (prevMonth != null) {
      year = month > prevMonth ? prevYear : prevYear + 1;
    } else {
      year = new Date().getFullYear();
    }
  }
  if (!month) return null; // not a month block (e.g. "رمضان" or similar one-off column)
  return { year, month };
}

function findMonthBlocks(sheet, XLSX) {
  const merges = sheet["!merges"] || [];
  const blocks = [];
  let prevYear = null;
  let prevMonth = null;
  merges
    .filter((m) => m.s.r === 0 && m.e.r === 0 && m.e.c - m.s.c >= 2) // row 1, at least 3-wide
    .sort((a, b) => a.s.c - b.s.c)
    .forEach((m) => {
      const label = sheet[XLSX.utils.encode_cell({ r: 0, c: m.s.c })]?.v;
      const parsed = parseMonthBlockLabel(label, prevYear, prevMonth);
      if (!parsed) return;
      blocks.push({ startCol: m.s.c, year: parsed.year, month: parsed.month });
      prevYear = parsed.year;
      prevMonth = parsed.month;
    });
  return blocks;
}

function cellStr(sheet, r, c, XLSX) {
  const cell = sheet[XLSX.utils.encode_cell({ r, c })];
  if (!cell || cell.v == null) return "";
  return String(cell.v).trim();
}

// Like cellStr, but for the "hour" column specifically: when Excel
// stores an actual time-of-day value (not typed as plain text), the
// cell comes through as a real JS Date object — stringifying that
// (like cellStr does) turns "3:30 PM" into a useless
// "Sat Dec 30 1899 15:30:00 GMT..." string that importMapTime can't
// read at all. This keeps the Date object intact so importMapTime's
// own Date-aware branch can pull the real hour/minute out of it, and
// only falls back to text for cells that were actually typed as text.
function cellRaw(sheet, r, c, XLSX) {
  const cell = sheet[XLSX.utils.encode_cell({ r, c })];
  if (!cell || cell.v == null) return "";
  if (cell.v instanceof Date) return cell.v;
  return String(cell.v).trim();
}

const IMPORT_LEVEL_MAP = {
  baby: "Baby", babya: "Baby",
  exp: "Exp", exp1: "Exp",
  exp2: "Exp 2", "exp 2": "Exp 2",
  exp3: "Exp 3", "exp 3": "Exp 3",
  "1": "Level 1", "2": "Level 2", "3": "Level 3", "4": "Level 4",
  "5": "Level 5", "6": "Level 6", "7": "Level 7", "8": "Level 8",
  star1: "Star 1", star2: "Star 2", star3: "Star 3", star4: "Star 4",
  team: "Team",
};
const IMPORT_DAY_MAP = {
  "الاحد": "sun-tue", "الاحد ": "sun-tue",
  "الثلاثاء": "sun-tue", "ثلاثاء": "sun-tue",
  "الاثنين": "mon-wed", "اثنين": "mon-wed",
  "الاربعاء": "mon-wed", "الاربع": "mon-wed",
  "الجمعة": "fri-sat", "الجمعه": "fri-sat", "جمعة": "fri-sat", "جمعه": "fri-sat",
  "السبت": "fri-sat",
};

// Matches a bare hour/time from the sheet (e.g. "3", "3:30", or a real
// Excel time) against this day group's actual valid time slots — those
// are the only values the app's Time dropdown can show as selected, and
// they carry the AM/PM the sheet's bare numbers don't specify. A bare
// hour on its own (just "3", no minutes) always means that hour and a
// half in this academy's real schedule (e.g. "3" -> 3:30) — that's the
// house convention the sheet was built around, confirmed against the
// real Star schedule (sheet says "4", the actual session is 4:30).
function importMapTime(raw, day) {
  if (raw == null || String(raw).trim() === "") return null;
  let hour, minute;
  if (raw instanceof Date) {
    hour = raw.getHours();
    minute = raw.getMinutes();
  } else {
    const s = String(raw).trim();
    if (/^\d{1,2}:\d{2}(:\d{2})?$/.test(s)) {
      const [h, m] = s.split(":");
      hour = Number(h);
      minute = Number(m);
    } else if (/^\d{1,2}$/.test(s)) {
      hour = Number(s);
      // A bare hour's real minute depends on the day group: Sunday/Tuesday
      // and Monday/Wednesday sessions are always on the half hour (e.g.
      // sheet's "3" -> 3:30); Friday/Saturday sessions are always right
      // on the hour (sheet's "4" -> 4:00, not 4:30).
      minute = day === "fri-sat" ? 0 : 30;
    } else {
      return null;
    }
  }
  const validSlots = (TIME_SLOTS[BRANCHES[0].id] && TIME_SLOTS[BRANCHES[0].id][day]) || [];
  const matched = validSlots.find((slot) => {
    const slotHour = parseInt(slot, 10);
    const slotMinuteMatch = slot.match(/:(\d{2})/);
    const slotMinute = slotMinuteMatch ? Number(slotMinuteMatch[1]) : 0;
    const is12h = /PM/i.test(slot) && slotHour !== 12 ? slotHour + 12 : /AM/i.test(slot) && slotHour === 12 ? 0 : slotHour;
    const hourMatches = is12h === hour || slotHour === hour;
    return hourMatches && slotMinute === minute;
  });
  // Only ever return one of the academy's real time slots — a bare
  // "H:MM" guess doesn't match anything in the Time dropdown, so it used
  // to save silently as a value the swimmer's edit form couldn't display,
  // making a swimmer LOOK unscheduled even though something was saved.
  // Returning null here instead lets the caller correctly treat this as
  // "couldn't determine a real time" (falls through to the Star/Team
  // category schedule, or shows the normal "left unscheduled" warning).
  return matched || null;
}

function parseFullHistorySheet(sheet, coaches = [], XLSX) {
  const blocks = findMonthBlocks(sheet, XLSX);
  if (blocks.length === 0) return null; // not this kind of sheet

  const range = XLSX.utils.decode_range(sheet["!ref"]);
  // Find the name / phone / notes / coach / session-type columns by their
  // header text, rather than assuming fixed positions — more forgiving
  // of small layout differences between exports (e.g. this app's own
  // "Export full history" button vs. an academy's original spreadsheet).
  let nameCol = null, birthCol = null, phoneCol = null, notesCol = null, coachCol = null, sessionTypeCol = null;
  for (let c = range.s.c; c <= range.e.c; c++) {
    const header = cellStr(sheet, 0, c, XLSX) || cellStr(sheet, 1, c, XLSX);
    if (!header) continue;
    if (nameCol == null && header.includes("اسم")) nameCol = c;
    if (birthCol == null && header.includes("مواليد")) birthCol = c;
    if (phoneCol == null && (header.includes("موبايل") || header.includes("تليفون") || header.includes("هاتف"))) phoneCol = c;
    if (notesCol == null && header.includes("ملاحظ")) notesCol = c;
    if (coachCol == null && (header.toLowerCase().includes("coach") || header.includes("كوتش") || header.includes("مدرب"))) coachCol = c;
    if (sessionTypeCol == null && (header.toLowerCase().includes("session") || header.includes("نوع الحصة") || header.includes("نوع الحصه"))) sessionTypeCol = c;
  }
  if (nameCol == null || phoneCol == null) return null; // doesn't look like this format after all

  // Each month block always has the same 4 sub-columns (payment, level,
  // day, time) but not always in the same left-to-right order — this
  // app's own "Export full history" writes Day/Time/Level/Payment, while
  // an academy's original spreadsheet migrated into the system might use
  // Payment/Level/Day/Time instead. Reading the actual sub-header text
  // for each block (rather than assuming a fixed order) makes the
  // importer work with either — and with anything exported later too.
  const detectSubColumns = (startCol) => {
    const offsets = { pay: 0, level: 1, day: 2, time: 3 }; // fallback: this app's historical default
    let found = 0;
    for (let i = 0; i < 4; i++) {
      const label = cellStr(sheet, 1, startCol + i, XLSX);
      if (!label) continue;
      if (label.includes("دفع") || label.toLowerCase().includes("pay")) {
        offsets.pay = i;
        found++;
      } else if (label.includes("مستو") || label.toLowerCase().includes("level")) {
        offsets.level = i;
        found++;
      } else if (label.includes("يوم") || label.toLowerCase().includes("day")) {
        offsets.day = i;
        found++;
      } else if (label.includes("ساع") || label.toLowerCase().includes("time") || label.includes("وقت")) {
        offsets.time = i;
        found++;
      }
    }
    // If we couldn't confidently read at least 3 of the 4 sub-headers
    // (e.g. a sheet with no sub-header row at all), fall back to the
    // original fixed order rather than guessing from partial matches.
    return found >= 3 ? offsets : { pay: 0, level: 1, day: 2, time: 3 };
  };
  const blockOffsets = blocks.map((b) => detectSubColumns(b.startCol));

  const latestBlock = blocks[blocks.length - 1];
  const latestKey = `${latestBlock.year}-${String(latestBlock.month).padStart(2, "0")}`;

  const swimmers = [];
  const warnings = [];
  for (let r = 2; r <= range.e.r; r++) {
    const name = cellStr(sheet, r, nameCol, XLSX);
    if (!name) continue;
    const birthYear = cellStr(sheet, r, birthCol, XLSX);
    const phoneRaw = cellStr(sheet, r, phoneCol, XLSX);
    const notes = notesCol != null ? cellStr(sheet, r, notesCol, XLSX) : "";
    const coachName = coachCol != null ? cellStr(sheet, r, coachCol, XLSX) : "";
    const sessionTypeLabel = sessionTypeCol != null ? cellStr(sheet, r, sessionTypeCol, XLSX) : "";

    const phoneParts = phoneRaw.split(/[-/]/).map((p) => p.replace(/\D/g, "")).filter(Boolean);
    const fixPhone = (p) => (p.length === 10 ? "0" + p : p);
    const phone = phoneParts[0] ? fixPhone(phoneParts[0]) : "";
    const altPhone = phoneParts[1] ? fixPhone(phoneParts[1]) : "";
    if (!phone) continue; // no usable phone — skip rather than guess

    const levelHistory = [];
    const scheduleHistory = [];
    const monthlySchedules = {}; // "YYYY-MM" -> { day, time, day2, time2, ... } — the same shape the rest of the app already reads per month via getMonthlySchedule()
    const paidMonths = [];

    // Matches the sheet's coach/session-type text back to real records —
    // only if those columns exist (e.g. a file this app exported itself);
    // an academy's original spreadsheet without them just leaves these
    // as null/default. These are per-swimmer metadata columns (not
    // repeated per month), so they're resolved once up front.
    const matchedCoach = coachName ? coaches.find((c) => c.name.trim().toLowerCase() === coachName.trim().toLowerCase()) : null;
    const matchedSessionType = sessionTypeLabel
      ? SESSION_TYPES.find((t) => t.label.toLowerCase() === sessionTypeLabel.trim().toLowerCase())?.id
      : null;

    blocks.forEach((b, bi) => {
      const off = blockOffsets[bi];
      const monthKeyStr = `${b.year}-${String(b.month).padStart(2, "0")}`;
      const monthDate = `${monthKeyStr}-01T00:00:00.000Z`;
      const payRaw = cellStr(sheet, r, b.startCol + off.pay, XLSX).toLowerCase();
      const lvlRaw = cellStr(sheet, r, b.startCol + off.level, XLSX);
      const dayRaw = cellStr(sheet, r, b.startCol + off.day, XLSX);
      const timeRaw = cellRaw(sheet, r, b.startCol + off.time, XLSX);

      // Accepts whatever this app's own export writes ("Yes") as well as
      // the original academy spreadsheet's convention ("تم" / "done").
      const isPaidThisMonth = ["تم", "done", "yes", "paid"].includes(payRaw);
      if (isPaidThisMonth) paidMonths.push(monthKeyStr);

      // A month is only skipped if it's genuinely blank across the
      // board — payment status on its own does NOT mean "not
      // registered". A swimmer can have a real level/day/time for a
      // month they haven't paid yet (attending with a balance due,
      // tracked separately via paidMonths) — that's still their real
      // data for that month, not something to hide. This also means a
      // level recorded for a later month is trusted even if it's LOWER
      // than before (e.g. after a long absence) rather than assuming
      // levels can only go up.
      if (!payRaw && !lvlRaw && !dayRaw && !timeRaw) return;

      const lvlKey = lvlRaw.trim().toLowerCase();
      const level = IMPORT_LEVEL_MAP[lvlKey];
      if (level) levelHistory.push({ level, date: monthDate });

      const day = IMPORT_DAY_MAP[dayRaw.trim()];
      const time = importMapTime(timeRaw, day);
      const baseSlot = { sessionType: matchedSessionType || "group", coachId: matchedCoach?.id || null, scheduleMonth: monthKeyStr };
      if (day && time) {
        scheduleHistory.push({ day, time, date: monthDate });
        monthlySchedules[monthKeyStr] = { ...baseSlot, day, time };
      } else {
        // Category placeholders instead of a real day/time — same
        // fallback schedule rules used for the offline migration.
        const blob = `${lvlRaw} ${dayRaw} ${timeRaw} ${payRaw}`.toLowerCase();
        if (blob.includes("star") || blob.includes("team") || blob.includes("بر تيم") || blob.includes("استار")) {
          scheduleHistory.push({ day: "mon-wed", time: "7:30 PM", date: monthDate });
          scheduleHistory.push({ day: "fri-sat", time: "3:00 PM", date: monthDate });
          monthlySchedules[monthKeyStr] = {
            ...baseSlot,
            day: "mon-wed", time: "7:30 PM",
            day2: "fri-sat", time2: "3:00 PM", sessionType2: matchedSessionType || "group",
          };
        } else if (blob.includes("ladies") || blob.includes("laides")) {
          scheduleHistory.push({ day: "fri-sat", time: "8:30 AM", date: monthDate });
          monthlySchedules[monthKeyStr] = { ...baseSlot, day: "fri-sat", time: "8:30 AM" };
        } else if (blob.includes("adult")) {
          scheduleHistory.push({ day: "sun-tue", time: "7:30 PM", date: monthDate });
          monthlySchedules[monthKeyStr] = { ...baseSlot, day: "sun-tue", time: "7:30 PM" };
        }
      }
    });

    // The flat day/time/level fields (used anywhere in the app that
    // doesn't look a specific month up in monthlySchedules) only reflect
    // the FILE'S actual latest month — a swimmer whose real data stops
    // in June (nothing since, paid or not) has left, and showing June's
    // old schedule as if it's their current one is exactly the "shows a
    // swimmer who wasn't really in August" mix-up this avoids. Whether
    // they've actually PAID for the latest month is a separate concern,
    // tracked via paidMonths — a real schedule/level with an unpaid
    // month still counts as active, just with a balance due.
    const latestMonthSlot = monthlySchedules[latestKey];
    const latestLevelEntry = levelHistory.find((h) => h.date === `${latestKey}-01T00:00:00.000Z`);
    const currentLevel = latestLevelEntry?.level || "";

    const age = birthYear && /^\d{4}$/.test(birthYear) ? new Date().getFullYear() - Number(birthYear) : "";

    swimmers.push({
      id: genId(),
      name,
      age: age || "",
      phone,
      altPhone,
      branch: BRANCHES[0].id,
      level: currentLevel,
      day: latestMonthSlot?.day || "",
      time: latestMonthSlot?.time || "",
      day2: latestMonthSlot?.day2 || "",
      time2: latestMonthSlot?.time2 || "",
      sessionType: latestMonthSlot?.sessionType || "group",
      sessionType2: latestMonthSlot?.day2 ? latestMonthSlot?.sessionType2 || "group" : "",
      coachId: latestMonthSlot?.coachId || null,
      coachId2: null,
      scheduleMonth: latestMonthSlot ? latestKey : undefined,
      notes,
      parentPin: genParentPin(),
      paidMonths,
      frozenUntil: null,
      freezeLog: [],
      levelHistory,
      scheduleHistory,
      monthlySchedules,
      trainingDates: [],
      attendance: {},
      createdAt: `${blocks[0].year}-${String(blocks[0].month).padStart(2, "0")}-01T00:00:00.000Z`,
    });
  }

  return { swimmers, monthsFound: blocks.length, latestMonthLabel: monthLabel(latestKey) };
}

/* Reads a raw spreadsheet row (keys are whatever the header cells said) and
   turns it into a swimmer record, being forgiving about column naming and
   casing. Returns { record, warnings } — warnings note any field that
   couldn't be matched and had to fall back to a default, so the person
   importing can go fix those specific swimmers afterward. Returns
   { error } instead if the row is missing something we can't default
   (no name, no phone). */
function parseImportedSwimmerRow(row, coaches) {
  const get = (...keys) => {
    for (const k of Object.keys(row)) {
      if (keys.some((want) => k.trim().toLowerCase() === want)) {
        const v = row[k];
        return v === undefined || v === null ? "" : String(v).trim();
      }
    }
    return "";
  };

  const name = get("name", "swimmer", "swimmer name", "الاسم", "اسم", "اسم السباح");
  if (!name) return { error: "Missing name" };

  // Egyptian mobile numbers are 11 digits starting with 0 (e.g. 01012345678).
  // Excel stores a cell typed as a plain number, not text — so it drops the
  // leading 0 and "01012345678" becomes 1012345678. Rebuild it when a phone
  // looks like exactly that: 10 digits, no leading 0.
  // Some rows also list two numbers in the same cell (a second parent's, or
  // a sibling's) separated by almost anything — a dash, slash, comma,
  // space, "و", a newline. Rather than guessing every possible separator,
  // just pull out the first run of 10-11 digits found anywhere in the
  // cell and use that; the rest of the cell is ignored.
  const phoneRaw = get("phone", "mobile", "phone number", "mobile number", "رقم الموبايل", "رقم الهاتف", "الموبايل", "موبايل");
  const phoneMatch = phoneRaw.match(/\d{10,11}/);
  let phone = phoneMatch ? phoneMatch[0] : "";
  if (/^\d{10}$/.test(phone)) phone = "0" + phone;
  if (!phone) return { error: "Missing phone number" };

  // A second number in the same cell (after the first) isn't dropped —
  // it goes in the notes so it's still there if needed, just not lost.
  let altPhone = "";
  if (phoneMatch) {
    const rest = phoneRaw.slice(phoneMatch.index + phoneMatch[0].length);
    const altMatch = rest.match(/\d{10,11}/);
    if (altMatch) {
      altPhone = /^\d{10}$/.test(altMatch[0]) ? "0" + altMatch[0] : altMatch[0];
    }
  }

  const warnings = [];

  // Age can come as a direct age, or as a birth year (e.g. "مواليد": 2019)
  const ageRaw = get("age", "العمر", "سن");
  let age = Number(ageRaw);
  if (!age || age <= 0) {
    const yearRaw = get("مواليد", "birth year", "year of birth", "dob year", "سنة الميلاد");
    const year = Number(yearRaw);
    if (year > 1990 && year <= new Date().getFullYear()) {
      age = new Date().getFullYear() - year;
    }
  }
  if (!age || age <= 0) warnings.push("no valid age — left blank, edit it after import");

  const branchRaw = get("branch", "الفرع").toLowerCase();
  const branchMatch = BRANCHES.find((b) => b.id.toLowerCase() === branchRaw || b.name.toLowerCase() === branchRaw);
  if (branchRaw && !branchMatch) warnings.push(`branch "${get("branch", "الفرع")}" not recognized — set to ${BRANCHES[0].name}`);
  const branch = branchMatch ? branchMatch.id : BRANCHES[0].id;

  const levelRaw = get("level", "المستوى", "مستوى");
  const levelMatch = LEVELS.find((l) => l.toLowerCase() === levelRaw.toLowerCase());
  if (levelRaw && !levelMatch) warnings.push(`level "${levelRaw}" not recognized — set to ${LEVELS[1]}`);
  const level = levelMatch || LEVELS[1];

  // Day/time are only set when the sheet actually specifies them. Rows with
  // no schedule info (the normal case for a fresh import) stay unscheduled —
  // same as adding a swimmer by hand — rather than all landing on one
  // default slot, which would wrongly stack everyone onto the same
  // day/time/coach capacity.
  const dayRaw = get("day", "day group", "schedule day", "اليوم", "الميعاد").toLowerCase();
  let day = "";
  if (dayRaw) {
    const dayMatch = DAY_GROUPS.find((d) => d.id.toLowerCase() === dayRaw || d.label.toLowerCase() === dayRaw);
    if (dayMatch) day = dayMatch.id;
    else warnings.push(`day "${get("day", "اليوم")}" not recognized — left unscheduled`);
  }

  const sessionRaw = get("session type", "sessiontype", "type", "نوع الحصة").toLowerCase();
  const sessionMatch = SESSION_TYPES.find((t) => t.id.toLowerCase() === sessionRaw || t.label.toLowerCase() === sessionRaw);
  if (sessionRaw && !sessionMatch) warnings.push(`session type "${get("session type", "نوع الحصة")}" not recognized — set to Group`);
  const sessionType = sessionMatch ? sessionMatch.id : "group";

  const timeRaw = get("time", "start time", "الوقت", "الساعة");
  let time = "";
  if (day && timeRaw) {
    const timeOptions = getTimeOptions(branch, day, level);
    const timeMatch = timeOptions.find((t) => t.toLowerCase() === timeRaw.toLowerCase());
    if (timeMatch) time = timeMatch;
    else warnings.push(`time "${timeRaw}" not on this branch/day's schedule — left unscheduled`);
  } else if (!day && timeRaw) {
    warnings.push(`time "${timeRaw}" given without a day — left unscheduled`);
  }

  const coachRaw = get("coach", "coach name", "الكابتن", "الكوتش").toLowerCase();
  const coachMatch = coachRaw ? (coaches || []).find((c) => c.name.toLowerCase() === coachRaw) : null;
  if (coachRaw && !coachMatch) warnings.push(`coach "${get("coach", "الكابتن")}" not found — left unassigned`);

  const notes = get("notes", "note", "ملاحظات");

  return {
    record: {
      id: genId(),
      name,
      age: age > 0 ? age : "",
      phone,
      altPhone,
      branch,
      level,
      day,
      time,
      sessionType,
      coachId: coachMatch ? coachMatch.id : null,
      notes,
      parentPin: genParentPin(),
      paidMonths: [],
      frozenUntil: null,
      freezeLog: [],
      levelHistory: [{ level, date: new Date().toISOString() }],
      trainingDates: [],
      attendance: {},
      createdAt: new Date().toISOString(),
    },
    warnings,
  };
}

// Compares an existing swimmer against a freshly-imported record and
// works out exactly what re-importing this row would change — schedule
// fields are replaced outright (that's the whole point: pick up a new
// booking), while paidMonths is merged (union) rather than replaced, so
// re-importing a file that only reflects this month's payment status can
// never accidentally erase a swimmer's payment history from an earlier
// month that just isn't in this particular sheet.
function diffSwimmerUpdate(existing, imported) {
  const changes = [];
  const fieldsToSync = ["day", "time", "level", "coachId", "sessionType", "branch", "age"];
  const patch = {};
  fieldsToSync.forEach((f) => {
    const newVal = imported[f];
    if (newVal !== undefined && newVal !== "" && newVal !== null && newVal !== existing[f]) {
      changes.push({ field: f, from: existing[f] ?? "—", to: newVal });
      patch[f] = newVal;
    }
  });
  const newlyPaid = (imported.paidMonths || []).filter((m) => !(existing.paidMonths || []).includes(m));
  if (newlyPaid.length > 0) {
    changes.push({ field: "paidMonths", from: null, to: newlyPaid.map(monthLabel).join(", ") });
    patch.paidMonths = [...(existing.paidMonths || []), ...newlyPaid];
  }
  return { changes, patch };
}

function dateLabel(iso) {
  return new Date(iso + "T00:00:00").toLocaleDateString("en-GB", {
    weekday: "short",
    day: "numeric",
    month: "short",
  });
}

function lastNDaysISO(n) {
  const arr = [];
  const now = new Date();
  for (let i = 0; i < n; i++) {
    const dt = new Date(now.getFullYear(), now.getMonth(), now.getDate() - i);
    arr.push(`${dt.getFullYear()}-${String(dt.getMonth() + 1).padStart(2, "0")}-${String(dt.getDate()).padStart(2, "0")}`);
  }
  return arr;
}

function attendanceCounts(swimmer, dateSet) {
  let present = 0;
  let absent = 0;
  for (const [d, status] of Object.entries(swimmer.attendance || {})) {
    if (dateSet.has(d)) {
      if (status === "present") present++;
      else if (status === "absent") absent++;
    }
  }
  return { present, absent };
}

// Marking a swimmer absent automatically grants one makeup credit;
// undoing that mark (toggling it off, or correcting it to present)
// takes the credit back. Keeps makeupCredits in sync with attendance
// so staff don't have to also remember to click the manual +/- control.
function applyAttendanceStatus(swimmer, date, status) {
  const attendance = { ...(swimmer.attendance || {}) };
  const prevStatus = attendance[date];
  const isToggleOff = prevStatus === status;
  const newStatus = isToggleOff ? undefined : status;

  if (newStatus === undefined) delete attendance[date];
  else attendance[date] = newStatus;

  let makeupCredits = swimmer.makeupCredits || 0;
  if (prevStatus === "absent" && newStatus !== "absent") makeupCredits = Math.max(0, makeupCredits - 1);
  if (prevStatus !== "absent" && newStatus === "absent") makeupCredits = makeupCredits + 1;

  return { ...swimmer, attendance, makeupCredits };
}

// Attendance rate, skill-mastery rate, parent rating, and pending makeup
// burden for one coach — computed straight from their currently-assigned
// swimmers (and those swimmers' feedback), no separate coach-performance
// data model needed. Parent rating is joined by each swimmer's CURRENT
// coach, same as attendance/skills below — feedback left while the
// swimmer had a different coach isn't separated out, since the app
// doesn't record who the coach was at the time.
function computeCoachPerformance(swimmers = [], coachId, feedback = []) {
  // Same month-aware resolver used everywhere else — a swimmer's CURRENT
  // coach can live in monthlySchedules rather than the top-level coachId.
  const mine = swimmers.filter((s) => {
    const ms = getMonthlySchedule(s, monthKey());
    return (ms ? ms.coachId : s.coachId) === coachId;
  });
  const mineIds = new Set(mine.map((s) => String(s.id)));
  let present = 0, absent = 0;
  let masteredTotal = 0, skillsTotal = 0;
  let makeupCreditsOwed = 0;

  mine.forEach((s) => {
    Object.values(s.attendance || {}).forEach((status) => {
      if (status === "present") present++;
      else if (status === "absent") absent++;
    });
    const levelSkills = LEVEL_SKILLS[s.level] || [];
    if (levelSkills.length > 0) {
      skillsTotal += levelSkills.length;
      masteredTotal += levelSkills.filter((sk) => (s.skills?.[s.level]?.[sk] || 0) >= 5).length;
    }
    makeupCreditsOwed += Number(s.makeupCredits || 0);
  });

  const myFeedback = feedback.filter((f) => mineIds.has(String(f.swimmerId)));
  const avgRating = myFeedback.length > 0
    ? Math.round((myFeedback.reduce((sum, f) => sum + Number(f.rating || 0), 0) / myFeedback.length) * 10) / 10
    : null;

  return {
    swimmerCount: mine.length,
    attendanceRate: present + absent > 0 ? Math.round((present / (present + absent)) * 100) : null,
    skillCompletionRate: skillsTotal > 0 ? Math.round((masteredTotal / skillsTotal) * 100) : null,
    makeupCreditsOwed,
    avgRating,
    ratingCount: myFeedback.length,
  };
}

function levelInMonth(swimmer, key) {
  const months = levelByMonth(swimmer);
  const found = months.find((m) => m.key === key);
  return found ? found.level : swimmer.level;
}

// Turns the academy's brand color (a "#rrggbb" hex string) into an
// rgba(...) string at the given opacity — used for the homepage hero's
// darkening overlays, which need partial transparency over a photo.
function academyColorRgba(alpha = 1) {
  const hex = (CONFIG.primaryColor || "#0369a1").replace("#", "");
  const r = parseInt(hex.slice(0, 2), 16) || 0;
  const g = parseInt(hex.slice(2, 4), 16) || 0;
  const b = parseInt(hex.slice(4, 6), 16) || 0;
  return `rgba(${r}, ${g}, ${b}, ${alpha})`;
}

function todayISO() {
  const d = new Date();
  return `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, "0")}-${String(d.getDate()).padStart(2, "0")}`;
}

// Some swimmers' "age" field actually has their birth year typed in
// instead (e.g. 2021) rather than years-old — a real age is always well
// under 100, so anything that looks like a calendar year gets converted
// to an actual age for display, without needing to fix the stored data.
function displayAge(age) {
  const n = Number(age);
  if (!n) return "";
  if (n >= 1900 && n <= new Date().getFullYear()) return new Date().getFullYear() - n;
  return n;
}

/* Generic Date -> "YYYY-MM-DD" (todayISO above is just this applied to "now") */
function toISODate(d) {
  return `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, "0")}-${String(d.getDate()).padStart(2, "0")}`;
}

/* The academy's week runs Saturday-Friday. Given any "YYYY-MM-DD", returns
   the Saturday that starts its week. */
function startOfWeekSat(dateStr) {
  const d = new Date(dateStr + "T00:00:00");
  const diff = (d.getDay() + 1) % 7; // days since the most recent Saturday
  return new Date(d.getFullYear(), d.getMonth(), d.getDate() - diff);
}

/* Returns { startISO, endISO, label } for a reporting period.
   type is "day" | "week" | "month"; anchor is a "YYYY-MM-DD" (day/week) or
   "YYYY-MM" (month) string picked by the user. */
function periodRange(type, anchor) {
  if (type === "day") {
    const d = new Date(anchor + "T00:00:00");
    return { startISO: anchor, endISO: anchor, label: d.toLocaleDateString("en-GB", { weekday: "long", day: "numeric", month: "long", year: "numeric" }) };
  }
  if (type === "week") {
    const start = startOfWeekSat(anchor);
    const end = new Date(start.getFullYear(), start.getMonth(), start.getDate() + 6);
    const startISO = toISODate(start);
    const endISO = toISODate(end);
    const fmt = (d) => d.toLocaleDateString("en-GB", { day: "numeric", month: "short" });
    return { startISO, endISO, label: `${fmt(start)} – ${fmt(end)}, ${end.getFullYear()}` };
  }
  // month
  const [y, m] = anchor.split("-").map(Number);
  const start = new Date(y, m - 1, 1);
  const end = new Date(y, m, 0);
  return { startISO: toISODate(start), endISO: toISODate(end), label: monthLabel(anchor) };
}

/* The anchor for the period immediately before this one — same length,
   so "this week vs last week" or "this month vs last month" compares
   like with like. Used for the "+20% over last period" KPI targets. */
function previousAnchor(type, anchor) {
  if (type === "day") {
    return toISODate(new Date(new Date(anchor + "T00:00:00").getTime() - 24 * 60 * 60 * 1000));
  }
  if (type === "week") {
    return toISODate(new Date(new Date(anchor + "T00:00:00").getTime() - 7 * 24 * 60 * 60 * 1000));
  }
  // month
  const [y, m] = anchor.split("-").map(Number);
  const d = new Date(y, m - 2, 1);
  return `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, "0")}`;
}

function inRange(dateStr, startISO, endISO) {
  return !!dateStr && dateStr >= startISO && dateStr <= endISO;
}

// Churn risk scoring — not machine learning, just a weighted checklist of
// the same warning signs an experienced admin would notice by eye
// (attendance dropping off, payment slipping, no progress for a while,
// recently frozen) turned into a 0-100 score so the whole roster can be
// sorted by who needs attention first, instead of relying on catching it
// swimmer by swimmer. Every point on the score traces back to a concrete,
// named reason, so it's always explainable, never a mystery number.
function calculateChurnRisk(swimmer) {
  const reasons = [];
  let score = 0;
  const today = new Date();
  const attendance = swimmer.attendance || {};
  const dates = Object.keys(attendance).sort();

  // Recent attendance trend — last 30 days vs the 30 days before that.
  const last30Start = new Date(today); last30Start.setDate(today.getDate() - 30);
  const prev30Start = new Date(today); prev30Start.setDate(today.getDate() - 60);
  const inWindow = (d, start, end) => { const dt = new Date(d); return dt >= start && dt <= end; };
  const last30 = dates.filter((d) => inWindow(d, last30Start, today));
  const prev30 = dates.filter((d) => inWindow(d, prev30Start, last30Start));
  const rate = (list) => (list.length ? list.filter((d) => attendance[d] === "present").length / list.length : null);
  const recentRate = rate(last30);
  const priorRate = rate(prev30);

  if (recentRate !== null && recentRate < 0.5) {
    score += 30;
    reasons.push(`Attendance dropped to ${Math.round(recentRate * 100)}% in the last 30 days`);
  }
  if (recentRate !== null && priorRate !== null && recentRate < priorRate - 0.2) {
    score += 20;
    reasons.push(`Attendance falling — was ${Math.round(priorRate * 100)}%, now ${Math.round(recentRate * 100)}%`);
  }
  if (last30.length === 0 && dates.length > 0) {
    score += 15;
    reasons.push("No sessions attended in the last 30 days");
  }

  // Payment — not paid this month, or a history of paying late/overdue.
  if (!(swimmer.paidMonths || []).includes(monthKey())) {
    score += 15;
    reasons.push("Hasn't paid this month yet");
  }

  // Frozen recently — may or may not come back once it ends.
  if (isFrozen(swimmer)) {
    score += 10;
    reasons.push("Subscription currently frozen");
  }

  // Stalled skill progress — been in the same level a while with no
  // ratings improving, while everything else about them still looks
  // "active" (they're not just new).
  const levelSkills = LEVEL_SKILLS[swimmer.level] || [];
  if (levelSkills.length > 0) {
    const anyProgress = levelSkills.some((sk) => (swimmer.skills?.[swimmer.level]?.[sk] || 0) > 0);
    const monthsSinceJoined = swimmer.createdAt
      ? Math.floor((today - new Date(swimmer.createdAt)) / (1000 * 60 * 60 * 24 * 30))
      : 0;
    if (!anyProgress && monthsSinceJoined >= 2) {
      score += 15;
      reasons.push(`No skill progress recorded in ${monthsSinceJoined} months at this level`);
    }
  }

  return { score: Math.min(100, score), reasons };
}

// Revenue forecasting — ordinary least-squares linear regression over the
// last several months of actual revenue, projected forward. Simple and
// transparent on purpose: a straight-line trend through recent months,
// not a black-box prediction — good enough to spot "we're growing" or
// "we're shrinking" and roughly by how much, without pretending to know
// more than the data supports.
function forecastRevenue(monthlyTotals, monthsAhead = 3) {
  const n = monthlyTotals.length;
  if (n < 2) return { forecasts: [], slope: 0, trending: "flat" };
  const xs = monthlyTotals.map((_, i) => i);
  const ys = monthlyTotals;
  const meanX = xs.reduce((a, b) => a + b, 0) / n;
  const meanY = ys.reduce((a, b) => a + b, 0) / n;
  const num = xs.reduce((sum, x, i) => sum + (x - meanX) * (ys[i] - meanY), 0);
  const den = xs.reduce((sum, x) => sum + (x - meanX) ** 2, 0);
  const slope = den === 0 ? 0 : num / den;
  const intercept = meanY - slope * meanX;

  const forecasts = [];
  for (let i = 0; i < monthsAhead; i++) {
    const x = n + i;
    const predicted = Math.max(0, Math.round(intercept + slope * x));
    forecasts.push(predicted);
  }
  return { forecasts, slope, trending: slope > meanY * 0.02 ? "up" : slope < -meanY * 0.02 ? "down" : "flat" };
}

/* Sunday/Tuesday, Monday/Wednesday, Friday/Saturday — Thursday has no group */
function dayGroupForToday() {
  const dow = new Date().getDay(); // 0=Sun..6=Sat
  if (dow === 0 || dow === 2) return "sun-tue";
  if (dow === 1 || dow === 3) return "mon-wed";
  if (dow === 5 || dow === 6) return "fri-sat";
  return null;
}

/* Turns a swimmer's levelHistory into "what level were they in each calendar month",
   carrying the level forward until the next recorded change */
function levelByMonth(swimmer) {
  const history = [...(swimmer.levelHistory || [])].sort((a, b) => new Date(a.date) - new Date(b.date));
  if (history.length === 0) return [];
  const months = [];
  const start = new Date(history[0].date);
  const now = new Date();
  let cursor = new Date(start.getFullYear(), start.getMonth(), 1);
  while (cursor <= now) {
    const key = `${cursor.getFullYear()}-${String(cursor.getMonth() + 1).padStart(2, "0")}`;
    // last history entry on/before this month
    let level = history[0].level;
    for (const h of history) {
      if (new Date(h.date) <= new Date(cursor.getFullYear(), cursor.getMonth() + 1, 0)) level = h.level;
      else break;
    }
    months.push({ key, level });
    cursor = new Date(cursor.getFullYear(), cursor.getMonth() + 1, 1);
  }
  return months.reverse();
}

/* ============================================================
   Visual signature: SVG wave divider
   ============================================================ */
function WaveDivider({ flip, className = "" }) {
  return (
    <svg
      viewBox="0 0 1200 60"
      preserveAspectRatio="none"
      className={`w-full h-10 ${flip ? "rotate-180" : ""} ${className}`}
    >
      <path
        d="M0,30 C150,60 350,0 600,30 C850,60 1050,0 1200,30 L1200,60 L0,60 Z"
        fill="currentColor"
      />
    </svg>
  );
}

/* A row of 5 tappable stars for rating a skill 0-5. Tapping the star that's
   already the current rating clears it back to 0. */
function StarRating({ value = 0, onChange, size = "w-4 h-4" }) {
  return (
    <div className="flex items-center gap-0.5">
      {[1, 2, 3, 4, 5].map((n) => (
        <button
          key={n}
          type="button"
          onClick={() => onChange(n === value ? 0 : n)}
          className="p-0.5"
        >
          <Star className={`${size} ${n <= value ? "fill-amber-400 text-amber-400" : "text-slate-300"}`} />
        </button>
      ))}
    </div>
  );
}

/* Read-only version — for coaches, who can see a swimmer's skill ratings
   but shouldn't be able to change them. */
function StarsDisplay({ value = 0, size = "w-3.5 h-3.5" }) {
  return (
    <div className="flex items-center gap-0.5">
      {[1, 2, 3, 4, 5].map((n) => (
        <Star key={n} className={`${size} ${n <= value ? "fill-amber-400 text-amber-400" : "text-slate-300"}`} />
      ))}
    </div>
  );
}

/* A visual progression path for a level's skills — connected nodes instead
   of a plain checklist, so a swimmer's journey through a level reads as a
   path rather than an unordered grid. Skills stay in the same order
   they're defined in LEVEL_SKILLS (already meant to be sequential), and
   each node's fill state comes from the exact same rating data as
   before — this only changes how it's presented, not what's stored.
   editable=false renders read-only (StarsDisplay under each node) for
   viewers who can see ratings but shouldn't change them. */
function SkillTreePath({ skills, ratings = {}, onRate, editable }) {
  return (
    <div className="overflow-x-auto pb-2">
      <div className="flex items-start" style={{ minWidth: skills.length * 132 }}>
        {skills.map((skill, i) => {
          const rating = ratings[skill] || 0;
          const mastered = rating >= 5;
          const started = rating > 0 && !mastered;
          return (
            <div key={skill} className="flex items-start" style={{ width: 132 }}>
              <div className="flex flex-col items-center text-center px-1">
                <div
                  className={`w-11 h-11 rounded-full flex items-center justify-center border-2 shrink-0 transition ${
                    mastered
                      ? "bg-green-500 border-green-500 text-white"
                      : started
                      ? "bg-amber-50 border-amber-400 text-amber-600"
                      : "bg-white border-slate-200 text-slate-300"
                  }`}
                >
                  {mastered ? <CheckCircle2 className="w-5 h-5" /> : <span className="text-xs font-bold">{i + 1}</span>}
                </div>
                <div className={`text-xs mt-2 leading-tight ${mastered ? "text-green-700 font-medium" : "text-slate-600"}`}>{skill}</div>
                <div className="mt-1.5">
                  {editable ? (
                    <StarRating value={rating} onChange={(n) => onRate(skill, n)} size="w-3.5 h-3.5" />
                  ) : (
                    <StarsDisplay value={rating} size="w-3 h-3" />
                  )}
                </div>
              </div>
              {i < skills.length - 1 && (
                <div className={`h-0.5 mt-[22px] flex-1 ${mastered ? "bg-green-400" : "bg-slate-200"}`} style={{ minWidth: 20 }} />
              )}
            </div>
          );
        })}
      </div>
    </div>
  );
}

/* A focused, single-swimmer view with its own tabs — Overview, Skills,
   Attendance, Payments — replacing the "everything in one expandable
   row" layout with something closer to a real profile page. Read-only
   for attendance/payment history (recording a NEW payment or attendance
   entry still happens from the Swimmers list/Attendance tab, which
   already do that well); this is for reviewing one swimmer's whole
   picture in one place. */
function SwimmerProfileModal({ swimmer: s, coaches, onClose, onEditSkill, canEditSkills }) {
  const { t } = useLang();
  const [profileTab, setProfileTab] = useState("overview");
  const coachName = coaches.find((c) => c.id === s.coachId)?.name;
  const dayLabel = DAY_GROUPS.find((d) => d.id === s.day)?.label;
  const skills = LEVEL_SKILLS[s.level] || [];
  const mastered = skills.filter((sk) => (s.skills?.[s.level]?.[sk] || 0) >= 5).length;

  const attendanceEntries = Object.entries(s.attendance || {}).sort((a, b) => b[0].localeCompare(a[0]));
  const presentCount = attendanceEntries.filter(([, status]) => status === "present").length;
  const absentCount = attendanceEntries.filter(([, status]) => status === "absent").length;
  const attendanceRate = attendanceEntries.length > 0 ? Math.round((presentCount / attendanceEntries.length) * 100) : null;

  const paidMonths = (s.paidMonths || []).slice().sort().reverse();
  const manualPayments = (s.manualPayments || []).slice().sort((a, b) => new Date(b.at) - new Date(a.at));

  const TABS = [
    { id: "overview", label: "Overview" },
    { id: "skills", label: "Skills" },
    { id: "attendance", label: "Attendance" },
    { id: "payments", label: "Payments" },
  ];

  return (
    <div className="fixed inset-0 bg-black/40 flex items-center justify-center p-4 z-50" onClick={onClose}>
      <div className="bg-white rounded-2xl w-full max-w-2xl max-h-[90vh] overflow-hidden flex flex-col" onClick={(e) => e.stopPropagation()}>
        <div className="p-5 border-b border-slate-100">
          <div className="flex items-start justify-between gap-3">
            <div>
              <h2 className="text-xl font-bold text-slate-900 tracking-tight">{s.name}</h2>
              <p className="text-sm text-slate-500 mt-0.5">{s.age} yrs · {s.level}</p>
            </div>
            <button onClick={onClose} className="p-1.5 rounded-lg hover:bg-slate-100 text-slate-400">
              <X className="w-5 h-5" />
            </button>
          </div>
          <div className="flex gap-1 mt-4 overflow-x-auto">
            {TABS.map((tb) => (
              <button
                key={tb.id}
                onClick={() => setProfileTab(tb.id)}
                className={`px-3 py-1.5 rounded-lg text-sm font-medium whitespace-nowrap transition ${
                  profileTab === tb.id ? "bg-sky-950 text-white" : "bg-slate-100 text-slate-500 hover:bg-slate-200"
                }`}
              >
                {tb.label}
              </button>
            ))}
          </div>
        </div>

        <div className="p-5 overflow-y-auto flex-1">
          {profileTab === "overview" && (
            <div className="space-y-4">
              <div className="grid grid-cols-2 gap-4 pb-4 border-b border-slate-100">
                <div>
                  <div className="text-xs text-slate-400 uppercase tracking-wide mb-1">Attendance</div>
                  <div className="text-2xl font-bold text-slate-900">{attendanceRate !== null ? `${attendanceRate}%` : "—"}</div>
                </div>
                <div>
                  <div className="text-xs text-slate-400 uppercase tracking-wide mb-1">Skills</div>
                  <div className="text-2xl font-bold text-slate-900">{skills.length > 0 ? `${mastered}/${skills.length}` : "—"}</div>
                </div>
              </div>
              <div className="grid sm:grid-cols-2 gap-x-6 gap-y-3 text-sm">
                <div>
                  <div className="text-xs text-slate-400">Phone</div>
                  <div className="text-slate-800">{s.phone || "—"}</div>
                </div>
                <div>
                  <div className="text-xs text-slate-400">Branch</div>
                  <div className="text-slate-800">{BRANCHES.find((b) => b.id === s.branch)?.name || "—"}</div>
                </div>
                <div>
                  <div className="text-xs text-slate-400">Schedule</div>
                  <div className="text-slate-800">{dayLabel ? `${dayLabel}${s.time ? ` · ${s.time}` : ""}` : "Unscheduled"}</div>
                </div>
                <div>
                  <div className="text-xs text-slate-400">Coach</div>
                  <div className="text-slate-800">{coachName || "No coach assigned"}</div>
                </div>
                <div>
                  <div className="text-xs text-slate-400">Session type</div>
                  <div className="text-slate-800">{sessionTypeInfo(s.sessionType).label}</div>
                </div>
                <div>
                  <div className="text-xs text-slate-400">Status</div>
                  <div className="text-slate-800">{isFrozen(s) ? "❄️ Frozen" : "Active"}</div>
                </div>
              </div>
              {s.notes && (
                <div className="pt-3 border-t border-slate-100">
                  <div className="text-xs text-slate-400 mb-1">Notes</div>
                  <div className="text-sm text-slate-600">{s.notes}</div>
                </div>
              )}
            </div>
          )}

          {profileTab === "skills" && (
            skills.length === 0 ? (
              <div className="text-sm text-slate-400 text-center py-10">No skills defined for this level yet</div>
            ) : (
              <SkillTreePath
                skills={skills}
                ratings={s.skills?.[s.level] || {}}
                editable={canEditSkills}
                onRate={(skill, n) => onEditSkill(s, skill, n)}
              />
            )
          )}

          {profileTab === "attendance" && (
            <div>
              <div className="flex items-center gap-4 mb-4 pb-4 border-b border-slate-100">
                <div>
                  <div className="text-xs text-slate-400 uppercase tracking-wide mb-1">Present</div>
                  <div className="text-xl font-bold text-green-600">{presentCount}</div>
                </div>
                <div>
                  <div className="text-xs text-slate-400 uppercase tracking-wide mb-1">Absent</div>
                  <div className="text-xl font-bold text-red-500">{absentCount}</div>
                </div>
                <div>
                  <div className="text-xs text-slate-400 uppercase tracking-wide mb-1">Rate</div>
                  <div className="text-xl font-bold text-slate-900">{attendanceRate !== null ? `${attendanceRate}%` : "—"}</div>
                </div>
              </div>
              {attendanceEntries.length === 0 ? (
                <div className="text-sm text-slate-400 text-center py-10">No attendance recorded yet</div>
              ) : (
                <div className="space-y-1">
                  {attendanceEntries.slice(0, 30).map(([date, status]) => (
                    <div key={date} className="flex items-center justify-between text-sm border-b border-slate-50 py-1.5">
                      <span className="text-slate-600">{new Date(date).toLocaleDateString("en-GB", { weekday: "short", day: "numeric", month: "short" })}</span>
                      <span className={`text-xs px-2 py-0.5 rounded-full font-medium ${status === "present" ? "bg-green-50 text-green-700" : "bg-red-50 text-red-600"}`}>
                        {status === "present" ? "Present" : "Absent"}
                      </span>
                    </div>
                  ))}
                </div>
              )}
            </div>
          )}

          {profileTab === "payments" && (
            <div>
              <div className="text-xs text-slate-400 uppercase tracking-wide mb-2">Paid months</div>
              {paidMonths.length === 0 ? (
                <div className="text-sm text-slate-400 text-center py-6">No payments recorded yet</div>
              ) : (
                <div className="flex flex-wrap gap-1.5 mb-4">
                  {paidMonths.map((m) => (
                    <span key={m} className="text-xs px-2.5 py-1 rounded-full bg-green-50 text-green-700 font-medium">{monthLabel(m)}</span>
                  ))}
                </div>
              )}
              {manualPayments.length > 0 && (
                <>
                  <div className="text-xs text-slate-400 uppercase tracking-wide mb-2 mt-4 pt-4 border-t border-slate-100">Marked paid only (no amount logged)</div>
                  <div className="space-y-1">
                    {manualPayments.map((p, i) => (
                      <div key={i} className="flex items-center justify-between text-sm border-b border-slate-50 py-1.5">
                        <span className="text-slate-600">{monthLabel(p.month)}</span>
                        <span className="text-xs text-slate-400">{new Date(p.at).toLocaleDateString("en-GB", { day: "numeric", month: "short", year: "numeric" })}</span>
                      </div>
                    ))}
                  </div>
                </>
              )}
            </div>
          )}
        </div>
      </div>
    </div>
  );
}

